var SA_P1 = [
  {"id":"pedsa1-1-1","src":"p1","num":"1.1","kind":"sba","block":"Block 1 · Growth and Puberty 14 QUESTIONS","page":3,"stem":"Which phase of growth accounts for the greatest proportion of final adult height?","options":["Fetal","Infantile","Childhood","Pubertal","Neonatal"],"answer":2,"keyLetter":"C","explanation":"Childhood ≈40%; fetal 30%; infantile and pubertal 15% each. The fetal phase is the fastest but not the largest contributor — read whether the stem says \"fastest\" or \"greatest proportion\"."},
  {"id":"pedsa1-1-2","src":"p1","num":"1.2","kind":"sba","block":"Block 1 · Growth and Puberty 14 QUESTIONS","page":3,"stem":"The main determinant of growth rate during the childhood phase is:","options":["Nutrition","Growth hormone acting through IGF-1","Testosterone and oestradiol","Maternal and placental health","Insulin"],"answer":1,"keyLetter":"B","explanation":"Nutrition dominates the infantile phase, sex steroids the pubertal phase, and maternal/placental factors the fetal phase. GH → IGF-1 at the epiphyses drives childhood growth, provided nutrition and health are adequate."},
  {"id":"pedsa1-1-3","src":"p1","num":"1.3","kind":"sba","block":"Block 1 · Growth and Puberty 14 QUESTIONS","page":4,"stem":"A girl's father is 180 cm and her mother 164 cm. What is her mid-parental height?","options":["158 cm","165 cm","172 cm","179 cm","186 cm"],"answer":1,"keyLetter":"B","explanation":"Mean = (180+164)/2 = 172 cm; she is a girl, so subtract 7 → 165 cm. The distractors are the unadjusted mean (172) and adding instead of subtracting (179)."},
  {"id":"pedsa1-1-4","src":"p1","num":"1.4","kind":"sba","block":"Block 1 · Growth and Puberty 14 QUESTIONS","page":4,"stem":"A baby born at 30 weeks' gestation is now 18 weeks old. Her weight plots below the 0.4th centile at actual age. What should be done before concluding she has faltering growth?","options":["Repeat the measurement on different scales","Plot at corrected age by subtracting 10 weeks","Measure the parents' heights","Check thyroid function","Refer for a skeletal survey"],"answer":1,"keyLetter":"B","explanation":"Correction for gestational age is used until 2 years. Corrected, she is likely between the 2nd and 9th centile — entirely different clinical picture."},
  {"id":"pedsa1-1-5","src":"p1","num":"1.5","kind":"sba","block":"Block 1 · Growth and Puberty 14 QUESTIONS","page":5,"stem":"A 13-year-old boy is short and has no pubertal development. Testicular volume is 3 ml, bone age is delayed by 2 years, and his father did not shave until 18. His growth has followed the 2nd centile throughout childhood. What is the most likely diagnosis?","options":["Growth hormone deficiency","Familial short stature","Constitutional delay of growth and puberty","Klinefelter syndrome","Hypothyroidism"],"answer":2,"keyLetter":"C","explanation":"Delayed bone age, delayed puberty, family history of late puberty, and a normal predicted final height. In familial short stature the bone age equals the chronological age and puberty is on time."},
  {"id":"pedsa1-1-6","src":"p1","num":"1.6","kind":"sba","block":"Block 1 · Growth and Puberty 14 QUESTIONS","page":5,"stem":"What is the most common endocrine cause of short stature?","options":["Growth hormone deficiency","Cushing syndrome","Acquired hypothyroidism","Congenital adrenal hyperplasia","IGF-1 deficiency (Laron syndrome)"],"answer":2,"keyLetter":"C","explanation":"And it often has few symptoms — which is why TSH is a standard first-line test in every short child."},
  {"id":"pedsa1-1-7","src":"p1","num":"1.7","kind":"sba","block":"Block 1 · Growth and Puberty 14 QUESTIONS","page":5,"stem":"All of the following are recognised patterns of premature sexual development EXCEPT:","options":["Premature thelarche","Premature adrenarche","Isolated premature menarche","Gonadotrophin-dependent precocious puberty","Constitutional delay of growth and puberty"],"answer":4,"keyLetter":"E","explanation":"CDGP is delayed, not premature, sexual development."},
  {"id":"pedsa1-1-8","src":"p1","num":"1.8","kind":"sba","block":"Block 1 · Growth and Puberty 14 QUESTIONS","page":6,"stem":"An 18-month-old girl has bilateral breast enlargement that fluctuates in size. Her growth rate is normal, there is no pubic or axillary hair, and no growth spurt. What is the most appropriate management?","options":["GnRH analogue therapy","Reassurance and observation","Urgent MRI of the brain","Bone age and pelvic ultrasound today","Karyotype"],"answer":1,"keyLetter":"B","explanation":"Premature thelarche: 6 months–2 years, may be asymmetrical and fluctuating, rarely beyond stage 3, non-progressive and self-limiting. The absence of a growth spurt and of pubic/axillary hair distinguishes it from true precocious puberty; investigations are not usually required."},
  {"id":"pedsa1-1-9","src":"p1","num":"1.9","kind":"sba","block":"Block 1 · Growth and Puberty 14 QUESTIONS","page":6,"stem":"A 7-year-old boy has pubic hair, an enlarged penis and a growth spurt. Both testes measure 10 ml. Which investigation is most likely to reveal the cause?","options":["17-hydroxyprogesterone","Testicular ultrasound","MRI of the brain","Karyotype","Thyroid function tests"],"answer":2,"keyLetter":"C","explanation":"Bilateral testicular enlargement >4 ml means the pituitary is driving it — gonadotrophin-dependent (central) precocious puberty. In boys this is pathological until proven otherwise, so image the brain (craniopharyngioma and other tumours). Prepubertal testes would point to CAH or an adrenal tumour; one enlarged testis to a Leydig cell tumour."},
  {"id":"pedsa1-1-10","src":"p1","num":"1.10","kind":"sba","block":"Block 1 · Growth and Puberty 14 QUESTIONS","page":7,"stem":"Which finding best distinguishes gonadotrophin-independent from gonadotrophin-dependent precocious puberty?","options":["The age of onset","The presence of a growth spurt","Whether the sequence of pubertal development is consonant or dissonant","The height of the oestradiol level","The presence of acne"],"answer":2,"keyLetter":"C","explanation":"Consonant (normal order and proportion) = central. Dissonant (out of order, e.g. virilisation before breast development) = peripheral."},
  {"id":"pedsa1-1-11","src":"p1","num":"1.11","kind":"sba","block":"Block 1 · Growth and Puberty 14 QUESTIONS","page":7,"stem":"A 15-year-old girl has not started puberty. She is 145 cm tall. LH and FSH are elevated. What is the most likely diagnosis?","options":["Constitutional delay","Anorexia nervosa","Turner syndrome","Kallmann syndrome","Craniopharyngioma"],"answer":2,"keyLetter":"C","explanation":"High gonadotrophins = primary gonadal failure (hypergonadotrophic hypogonadism). In a short girl this is Turner syndrome until the karyotype says otherwise. All the other options give low gonadotrophins."},
  {"id":"pedsa1-1-12","src":"p1","num":"1.12","kind":"sba","block":"Block 1 · Growth and Puberty 14 QUESTIONS","page":8,"stem":"A 6-month-old has occipital flattening on the right, with the right ear displaced anteriorly and a normal head circumference. No ridge is palpable. Which statement is correct?","options":["Urgent surgical referral is needed","He should now be placed prone to sleep","This is positional plagiocephaly and improves with mobility","A skull X-ray will show a fused lambdoid suture","The head circumference will fall across centiles"],"answer":2,"keyLetter":"C","explanation":"Anteriorly displaced ear, all sutures open, normal head circumference. Lambdoid synostosis displaces the ear posteriorly and gives a palpable ridge. The baby must still sleep supine — SIDS prevention outweighs the cosmetic issue."},
  {"id":"pedsa1-1-13","src":"p1","num":"1.13","kind":"sba","block":"Block 1 · Growth and Puberty 14 QUESTIONS","page":8,"stem":"What is the most common cause of a head circumference above the 98th centile in a developmentally normal infant?","options":["Hydrocephalus","Familial macrocephaly","Sotos syndrome","Chronic subdural haematoma","Mucopolysaccharidosis"],"answer":1,"keyLetter":"B","explanation":"Measure the parents' heads. The concerning pattern is a head circumference crossing centiles upwards, which needs cranial ultrasound (if the fontanelle is open) or CT/MRI."},
  {"id":"pedsa1-1-14","src":"p1","num":"1.14","kind":"sba","block":"Block 1 · Growth and Puberty 14 QUESTIONS","page":9,"stem":"A 16-year-old boy is 196 cm tall with long limbs, arachnodactyly and a high-arched palate. Which investigation must not be omitted?","options":["Karyotype","Growth hormone suppression test","Echocardiography","Thyroid function tests","Bone age"],"answer":2,"keyLetter":"C","explanation":"Marfan syndrome — the complication that kills is aortic root dilatation. Homocystinuria is the main differential and is excluded biochemically."},
  {"id":"pedsa1-2-1","src":"p1","num":"2.1","kind":"sba","block":"Block 2 · Nutrition 14 QUESTIONS","page":10,"stem":"A term newborn, after the first week of life, requires approximately what daily volume of milk?","options":["60 ml/kg","100 ml/kg","150 ml/kg","200 ml/kg","250 ml/kg"],"answer":2,"keyLetter":"C","explanation":"150 ml/kg/day — about 15% of body weight every day, which is why even a small reduction in intake rapidly affects hydration, nutrition and growth."},
  {"id":"pedsa1-2-2","src":"p1","num":"2.2","kind":"sba","block":"Block 2 · Nutrition 14 QUESTIONS","page":10,"stem":"Which hormone is responsible for the milk-ejection (\"let-down\") reflex?","options":["Prolactin","Oxytocin","Oestrogen","Progesterone","Human placental lactogen"],"answer":1,"keyLetter":"B","explanation":"Prolactin makes the milk (cuboidal alveolar cells); oxytocin contracts the myoepithelial cells to eject it — and contracts the uterus, reducing postpartum blood loss."},
  {"id":"pedsa1-2-3","src":"p1","num":"2.3","kind":"sba","block":"Block 2 · Nutrition 14 QUESTIONS","page":11,"stem":"A mother says her milk supply is falling. Which explanation is physiologically correct?","options":["Prolactin levels fall progressively after birth regardless of feeding","Milk left in the breast accumulates feedback inhibitor of lactation, suppressing secretion","Oxytocin release is inhibited by frequent suckling","Supply is fixed by the third day and cannot be increased","Colostrum production continues for 6 weeks"],"answer":1,"keyLetter":"B","explanation":"FIL is the local control mechanism: an unemptied breast switches secretion off. The management is more frequent feeding or expression, not medication."},
  {"id":"pedsa1-2-4","src":"p1","num":"2.4","kind":"sba","block":"Block 2 · Nutrition 14 QUESTIONS","page":11,"stem":"Which is the primary anti-infective agent in breast milk?","options":["Lactoferrin","Lysozyme","Secretory IgA","Human milk oligosaccharides","Maternal leucocytes"],"answer":2,"keyLetter":"C","explanation":"Secretory IgA coats the intestinal mucosa and prevents bacteria entering the cells. The others all contribute but sIgA is the primary agent."},
  {"id":"pedsa1-2-5","src":"p1","num":"2.5","kind":"sba","block":"Block 2 · Nutrition 14 QUESTIONS","page":11,"stem":"A term breastfed baby has lost 12% of his birthweight on day 6. What is the correct action?","options":["Reassure — up to 15% loss is normal","Stop breastfeeding and start formula","Assess the baby for an underlying medical problem and support feeding","Wait until day 14 and reassess","Start phototherapy"],"answer":2,"keyLetter":"C","explanation":"Normal loss is 7–10%, regained by 14 days. More than 10%, or failure to regain by 14 days, requires assessment — feeding problems, dehydration, infection, or metabolic disease."},
  {"id":"pedsa1-2-6","src":"p1","num":"2.6","kind":"sba","block":"Block 2 · Nutrition 14 QUESTIONS","page":12,"stem":"All of the following are advantages of breastfeeding for the INFANT EXCEPT:","options":["Reduced risk of necrotising enterocolitis","Reduced risk of sudden infant death syndrome","Reduced risk of maternal breast cancer","Reduced incidence of later obesity and diabetes","Higher IQ score by approximately 3 points"],"answer":2,"keyLetter":"C","explanation":"Reduced breast (and probably ovarian) cancer risk is a benefit to the mother. Read whether the question asks about the infant or the mother."},
  {"id":"pedsa1-2-7","src":"p1","num":"2.7","kind":"sba","block":"Block 2 · Nutrition 14 QUESTIONS","page":12,"stem":"Which is an absolute contraindication to breastfeeding?","options":["Breast milk jaundice","Galactosaemia in the infant","Maternal mastitis","Prematurity","Maternal hepatitis B when the infant has been immunised"],"answer":1,"keyLetter":"B","explanation":"Galactosaemia and fatty-acid oxidation disorders contraindicate breastfeeding. Breast milk jaundice is benign — continue feeding and investigate only if it lasts beyond 2 weeks."},
  {"id":"pedsa1-2-8","src":"p1","num":"2.8","kind":"sba","block":"Block 2 · Nutrition 14 QUESTIONS","page":12,"stem":"Why is unmodified cow's milk unsuitable as the main drink before 12 months of age?","options":["It contains too little protein","It has a very low bioavailable iron content and a high renal solute load","It is deficient in carbohydrate and cannot sustain growth","It causes lactose intolerance","It has a whey-dominant protein profile"],"answer":1,"keyLetter":"B","explanation":"Cow's milk has 3× the protein and 3× the sodium of breast milk, a casein-dominant 80:20 ratio, and almost no absorbable iron — hence iron-deficiency anaemia. It may be used in cooking."},
  {"id":"pedsa1-2-9","src":"p1","num":"2.9","kind":"sba","block":"Block 2 · Nutrition 14 QUESTIONS","page":13,"stem":"Which formula is indicated for an infant with cholestatic liver disease and fat malabsorption?","options":["Soya-based formula","Anti-reflux (thickened) formula","Medium-chain triglyceride formula","Standard whey-dominant formula","Amino acid formula"],"answer":2,"keyLetter":"C","explanation":"MCTs are absorbed without pancreatic enzymes or bile salts. Amino acid formula is for cow's-milk protein allergy; soya is avoided in the first 6–12 months."},
  {"id":"pedsa1-2-10","src":"p1","num":"2.10","kind":"sba","block":"Block 2 · Nutrition 14 QUESTIONS","page":13,"stem":"A 13-month-old exclusively breastfed boy has an afebrile generalised seizure. He has frontal bossing, widened wrists and delayed motor milestones. Which biochemical pattern do you expect?","options":["Low calcium, high phosphate, low PTH","Low calcium, low phosphate, high alkaline phosphatase, high PTH","High calcium, low phosphate, high PTH","Normal calcium, normal phosphate, normal alkaline phosphatase","Low calcium, low phosphate, low alkaline phosphatase"],"answer":1,"keyLetter":"B","explanation":"Nutritional rickets. Option A is hypoparathyroidism. Remember that vitamin D deficiency can present with a hypocalcaemic seizure before any bone deformity, especially under 2 years and in adolescence."},
  {"id":"pedsa1-2-11","src":"p1","num":"2.11","kind":"sba","block":"Block 2 · Nutrition 14 QUESTIONS","page":13,"stem":"Where is vitamin D converted to its most active form?","options":["Skin","Liver","Kidney","Small intestine","Bone"],"answer":2,"keyLetter":"C","explanation":"Skin makes D3; the liver does 25-hydroxylation (the storage form you measure); the kidney does 1α-hydroxylation to 1,25-dihydroxyvitamin D. Hence rickets in chronic kidney disease."},
  {"id":"pedsa1-2-12","src":"p1","num":"2.12","kind":"sba","block":"Block 2 · Nutrition 14 QUESTIONS","page":14,"stem":"A 3-year-old refugee has a mid-upper arm circumference of 108 mm, generalised pitting oedema, sparse depigmented hair and refuses to eat. Which is most likely to be abnormal?","options":["Serum albumin","Serum sodium (high)","Haematocrit (high)","Serum calcium (high)","Alkaline phosphatase (low)"],"answer":0,"keyLetter":"A","explanation":"Kwashiorkor: oedema, low albumin, apathy and anorexia, with sparse depigmented hair and a flaky-paint rash. Marasmus has normal albumin, no oedema, and an irritable hungry child. MUAC <115 mm confirms severe acute malnutrition."},
  {"id":"pedsa1-2-13","src":"p1","num":"2.13","kind":"sba","block":"Block 2 · Nutrition 14 QUESTIONS","page":14,"stem":"Which is INCORRECT in the initial management of severe acute malnutrition?","options":["Treat or prevent hypoglycaemia urgently","Give broad-spectrum antibiotics even without fever","Give standard oral rehydration solution freely","Start small, frequent F-75 feeds including overnight","Delay iron until the second week"],"answer":2,"keyLetter":"C","explanation":"Standard ORS has too much sodium and too little potassium for these children, who already have excess total body sodium. IV fluids are used only for shock, and too much fluid causes heart failure."},
  {"id":"pedsa1-2-14","src":"p1","num":"2.14","kind":"sba","block":"Block 2 · Nutrition 14 QUESTIONS","page":15,"stem":"A 9-year-old boy has a BMI on the 99th centile. He is on the 9th height centile and has mild learning difficulty. Which is the most appropriate assessment?","options":["Reassure — this is simple obesity","Investigate for an endocrine or genetic cause","Start orlistat","Refer for bariatric surgery","Advise a very low calorie diet alone"],"answer":1,"keyLetter":"B","explanation":"Simple (exogenous) obesity makes children tall for age. Obesity with short stature, developmental delay or dysmorphism points to hypothyroidism, Cushing syndrome, GH deficiency or a genetic syndrome such as Prader–Willi. Drugs and surgery are for a small minority."},
  {"id":"pedsa1-3-1","src":"p1","num":"3.1","kind":"sba","block":"Block 3 · Gastroenterology 18 QUESTIONS · HIGHEST WEIGHT","page":16,"stem":"A 7-year-old has right iliac fossa pain for 18 hours with anorexia and a temperature of 38.0 °C. The white cell count and ultrasound are normal. What is the most appropriate next step?","options":["Discharge with safety-netting","Admit for repeated clinical review","Abdominal CT","Immediate laparotomy","Barium enema"],"answer":1,"keyLetter":"B","explanation":"Appendicitis is a progressive condition and no test reliably excludes it — normal neutrophils and a normal ultrasound do not. Serial examination every few hours is the standard answer."},
  {"id":"pedsa1-3-2","src":"p1","num":"3.2","kind":"sba","block":"Block 3 · Gastroenterology 18 QUESTIONS · HIGHEST WEIGHT","page":16,"stem":"In a child with acute abdominal pain, all of the following must be examined or excluded EXCEPT:","options":["The chest, for lower lobe pneumonia","The urine, for infection","The blood glucose, for diabetic ketoacidosis","The testes and hernial orifices","The fundi, for papilloedema"],"answer":4,"keyLetter":"E","explanation":"The other four are the standard \"do not miss\" list in your notes. Fundoscopy has its place in headache and raised intracranial pressure, not routinely in the acute abdomen."},
  {"id":"pedsa1-3-3","src":"p1","num":"3.3","kind":"sba","block":"Block 3 · Gastroenterology 18 QUESTIONS · HIGHEST WEIGHT","page":17,"stem":"A 9-month-old has episodes of screaming during which he goes pale and draws up his legs, with quiet lethargy between. He has vomited twice. A sausage-shaped mass is felt in the upper abdomen. What is the investigation of choice?","options":["Plain abdominal X-ray","Abdominal ultrasound","Technetium scan","Upper GI contrast study","CT abdomen"],"answer":1,"keyLetter":"B","explanation":"Intussusception — ultrasound shows the target/doughnut sign and is used to check response to treatment. Note that a redcurrant jelly stool is a late sign and its absence means nothing here."},
  {"id":"pedsa1-3-4","src":"p1","num":"3.4","kind":"sba","block":"Block 3 · Gastroenterology 18 QUESTIONS · HIGHEST WEIGHT","page":17,"stem":"In the child above, air enema reduction is planned. Which is the correct sequence?","options":["Air enema first, then IV fluids if he becomes shocked","IV fluid resuscitation first, with a paediatric surgeon available","Immediate laparotomy in all cases","Oral rehydration then discharge","Air enema even if there are signs of peritonitis"],"answer":1,"keyLetter":"B","explanation":"Fluid pools in the gut, so hypovolaemic shock is common and resuscitation comes first. Success rate ≈75%; peritonitis is a contraindication to enema reduction."},
  {"id":"pedsa1-3-5","src":"p1","num":"3.5","kind":"sba","block":"Block 3 · Gastroenterology 18 QUESTIONS · HIGHEST WEIGHT","page":18,"stem":"A 2-day-old term infant vomits bile-stained fluid. The abdomen is soft and he is otherwise well. What is the most appropriate action?","options":["Observe and reassess in 12 hours","Trial of thickened feeds","Urgent upper gastrointestinal contrast study","Abdominal ultrasound for pyloric stenosis","Rectal biopsy"],"answer":2,"keyLetter":"C","explanation":"Bilious vomiting in a neonate is intestinal obstruction until proven otherwise — malrotation with volvulus can infarct the entire midgut within hours. A soft abdomen is falsely reassuring."},
  {"id":"pedsa1-3-6","src":"p1","num":"3.6","kind":"sba","block":"Block 3 · Gastroenterology 18 QUESTIONS · HIGHEST WEIGHT","page":18,"stem":"A 4-year-old has painless but massive rectal bleeding that is neither bright red nor melaena, with an acute fall in haemoglobin. Which investigation is most useful?","options":["Colonoscopy","Technetium scan","Barium enema","Faecal calprotectin","Abdominal ultrasound"],"answer":1,"keyLetter":"B","explanation":"Meckel diverticulum — technetium shows uptake by ectopic gastric mucosa in about 70%. A negative scan does not exclude it, and laparoscopy may be needed."},
  {"id":"pedsa1-3-7","src":"p1","num":"3.7","kind":"sba","block":"Block 3 · Gastroenterology 18 QUESTIONS · HIGHEST WEIGHT","page":19,"stem":"Which feature most suggests an organic cause in a school-age child with recurrent abdominal pain?","options":["Periumbilical pain","Pain relieved by defecation","Pain that wakes the child at night","Symptoms worse before school","A family history of irritable bowel syndrome"],"answer":2,"keyLetter":"C","explanation":"Night waking and pain away from the umbilicus are red flags; so are vomiting, weight loss, blood in the stool, dysphagia, perianal disease and delayed puberty. Fewer than 10% of recurrent abdominal pain is organic."},
  {"id":"pedsa1-3-8","src":"p1","num":"3.8","kind":"sba","block":"Block 3 · Gastroenterology 18 QUESTIONS · HIGHEST WEIGHT","page":19,"stem":"A 9-year-old has episodes of severe midline abdominal pain lasting several hours, with pallor, nausea and photophobia, and is entirely well for weeks between. His mother has migraine. What is the diagnosis?","options":["Irritable bowel syndrome","Abdominal migraine","Functional dyspepsia","Peptic ulcer disease","Recurrent appendicitis"],"answer":1,"keyLetter":"B","explanation":"Paroxysms lasting ≥1 hour, long symptom-free intervals, migraine family history, same triggers and relieving factors, and associated pallor, anorexia, vomiting and photophobia."},
  {"id":"pedsa1-3-9","src":"p1","num":"3.9","kind":"sba","block":"Block 3 · Gastroenterology 18 QUESTIONS · HIGHEST WEIGHT","page":20,"stem":"A 6-week-old boy has forceful non-bilious vomiting after every feed and has lost weight. He is hungry after vomiting. A wave is seen moving across the abdomen. What is the immediate priority?","options":["Pyloromyotomy today","Correction of fluid and electrolyte abnormalities","Start a proton-pump inhibitor","Upper GI contrast study","Change to an anti-reflux formula"],"answer":1,"keyLetter":"B","explanation":"Pyloric stenosis causes hypochloraemic hypokalaemic metabolic alkalosis; correction may take more than 24 hours and must precede surgery. Diagnosis is by test feed and ultrasound."},
  {"id":"pedsa1-3-10","src":"p1","num":"3.10","kind":"sba","block":"Block 3 · Gastroenterology 18 QUESTIONS · HIGHEST WEIGHT","page":20,"stem":"Which feature would make you doubt a diagnosis of uncomplicated gastro-oesophageal reflux in a 4-month-old?","options":["Effortless regurgitation after feeds","Six or more episodes each day","Weight tracking along the 50th centile","Faltering growth with recurrent chest infections","The infant is otherwise well"],"answer":3,"keyLetter":"D","explanation":"That is GORD — reflux causing harm. Other harm markers: oesophagitis with haematemesis or iron-deficiency anaemia, apnoea in preterms, and Sandifer syndrome (dystonic neck posturing)."},
  {"id":"pedsa1-3-11","src":"p1","num":"3.11","kind":"sba","block":"Block 3 · Gastroenterology 18 QUESTIONS · HIGHEST WEIGHT","page":21,"stem":"A 2-year-old with gastroenteritis has been drinking large volumes of water. He has a seizure. Serum sodium is 124 mmol/L. What is the mechanism?","options":["Water moves out of the brain, causing cerebral shrinkage","Water moves into cells, increasing brain volume","Cerebral vasospasm","Hypoglycaemia","Hypocalcaemia from bicarbonate loss"],"answer":1,"keyLetter":"B","explanation":"Hyponatraemic dehydration: extracellular hypotonicity drives water into cells → increased brain volume → seizures, plus early exaggerated peripheral signs and early shock. Hypernatraemia does the opposite (cerebral shrinkage)."},
  {"id":"pedsa1-3-12","src":"p1","num":"3.12","kind":"sba","block":"Block 3 · Gastroenterology 18 QUESTIONS · HIGHEST WEIGHT","page":21,"stem":"A child with hypernatraemic dehydration has a sodium of 162 mmol/L. What rate of correction is appropriate?","options":["As fast as possible with 5% dextrose","Reduce sodium by less than 0.5 mmol/L per hour over at least 48 hours","Reduce sodium by 2 mmol/L per hour","Give 0.45% saline as a rapid bolus","Restrict all fluids for 24 hours"],"answer":1,"keyLetter":"B","explanation":"Rapid correction causes cerebral oedema and seizures. Use 0.9% saline (± 5% glucose) tailored to response, with regular sodium measurement."},
  {"id":"pedsa1-3-13","src":"p1","num":"3.13","kind":"sba","block":"Block 3 · Gastroenterology 18 QUESTIONS · HIGHEST WEIGHT","page":22,"stem":"Why does oral rehydration solution work in diarrhoeal illness?","options":["It stops the diarrhoea by slowing gut transit","Glucose drives active sodium co-transport, which drags water across the mucosa","It is hypertonic and draws water into the circulation","It kills the causative organism","It replaces bicarbonate lost in the stool only"],"answer":1,"keyLetter":"B","explanation":"The glucose-coupled sodium transporter remains intact in diarrhoeal illness. ORS does not stop the diarrhoea — it keeps the child hydrated until the organism is cleared. Fruit juices and carbonated drinks are unsuitable."},
  {"id":"pedsa1-3-14","src":"p1","num":"3.14","kind":"sba","block":"Block 3 · Gastroenterology 18 QUESTIONS · HIGHEST WEIGHT","page":22,"stem":"A 24 kg child needs maintenance IV fluids. What is the 24-hour volume?","options":["1200 ml","1440 ml","1580 ml","1800 ml","2400 ml"],"answer":2,"keyLetter":"C","explanation":"100 ml/kg × 10 = 1000, plus 50 ml/kg × 10 = 500, plus 20 ml/kg × 4 = 80 → 1580 ml/24 h."},
  {"id":"pedsa1-3-15","src":"p1","num":"3.15","kind":"sba","block":"Block 3 · Gastroenterology 18 QUESTIONS · HIGHEST WEIGHT","page":23,"stem":"A 9-year-old has iron-deficiency anaemia that has not responded to 3 months of oral iron. She has intermittent abdominal pain and is on the 9th height centile. What is the most appropriate investigation?","options":["Faecal calprotectin","IgA tissue transglutaminase antibody with total IgA","Upper GI endoscopy first","Abdominal ultrasound","Bone marrow aspirate"],"answer":1,"keyLetter":"B","explanation":"Unexplained iron-deficiency anaemia resistant to treatment, with short stature, is a classic modern presentation of coeliac disease. She must stay on gluten until tested, and total IgA is measured because IgA deficiency gives a false negative."},
  {"id":"pedsa1-3-16","src":"p1","num":"3.16","kind":"sba","block":"Block 3 · Gastroenterology 18 QUESTIONS · HIGHEST WEIGHT","page":23,"stem":"A 3-year-old passes 4–5 stools a day of varying consistency containing recognisable vegetables. He is thriving and well, and coeliac serology is negative. What is the most likely diagnosis?","options":["Chronic non-specific (\"toddler\") diarrhoea","Crohn disease","Cystic fibrosis","Giardiasis","Lactose intolerance"],"answer":0,"keyLetter":"A","explanation":"The commonest cause of persistent loose stools in preschool children; the child is well and thriving. Ask about excessive fruit juice, especially apple juice. It improves with age."},
  {"id":"pedsa1-3-17","src":"p1","num":"3.17","kind":"sba","block":"Block 3 · Gastroenterology 18 QUESTIONS · HIGHEST WEIGHT","page":24,"stem":"A 4-year-old has faecal impaction with overflow soiling. What is the first-line treatment?","options":["Increase dietary fibre and fluids alone","Oral macrogol in an escalating dose over 1–2 weeks","Phosphate enema","Manual evacuation under anaesthesia","Stop all laxatives because of the soiling"],"answer":1,"keyLetter":"B","explanation":"Overflow soiling means more laxative, not less. Add a stimulant if macrogol alone fails; substitute lactulose if macrogol is not tolerated. Dietary intervention alone has no benefit."},
  {"id":"pedsa1-3-18","src":"p1","num":"3.18","kind":"sba","block":"Block 3 · Gastroenterology 18 QUESTIONS · HIGHEST WEIGHT","page":24,"stem":"A 4-week-old has abdominal distension and bile-stained vomiting. He did not pass meconium until 36 hours of age. Rectal examination releases a gush of liquid stool. What confirms the diagnosis?","options":["Barium enema","Anorectal manometry","Suction rectal biopsy","Abdominal ultrasound","Sweat test"],"answer":2,"keyLetter":"C","explanation":"Hirschsprung disease — biopsy shows absent ganglion cells with large acetylcholinesterase-positive nerve trunks. Barium and manometry only estimate the length of the aganglionic segment."},
  {"id":"pedsa1-4-1","src":"p1","num":"4.1","kind":"sba","block":"Block 4 · Accidents and Poisoning 7 QUESTIONS","page":25,"stem":"What is the most common cause of non-fatal choking in children?","options":["Toys","Food","Coins","Button batteries","Balloons"],"answer":1,"keyLetter":"B","explanation":"Food first, toys second. Young children are vulnerable because their airway diameter is small and easily occluded."},
  {"id":"pedsa1-4-2","src":"p1","num":"4.2","kind":"sba","block":"Block 4 · Accidents and Poisoning 7 QUESTIONS","page":25,"stem":"An 8-month-old is choking, conscious, with an ineffective cough. What should be done?","options":["Abdominal thrusts","Blind finger sweep","Five back blows then five chest thrusts","Immediate chest compressions","Encourage coughing only"],"answer":2,"keyLetter":"C","explanation":"Under 1 year: no abdominal thrusts — the liver and spleen are large and unprotected. Never do a blind finger sweep; remove only what you can see. If the child becomes unconscious, start CPR."},
  {"id":"pedsa1-4-3","src":"p1","num":"4.3","kind":"sba","block":"Block 4 · Accidents and Poisoning 7 QUESTIONS","page":26,"stem":"A 6-year-old is pulled from cold water. He is apnoeic with fixed dilated pupils and a core temperature of 28 °C. What is correct?","options":["Resuscitation should be stopped — the pupils are fixed","Resuscitation should continue until he is rewarmed to normal body temperature","Fixed pupils confirm brain death in hypothermia","He should be rewarmed rapidly to 39 °C","Resuscitation is futile below 30 °C"],"answer":1,"keyLetter":"B","explanation":"\"Nobody is dead until they are warm and dead.\" Hypothermia is neuroprotective and recovery is still possible. Up to 30% of drowning deaths can be prevented by skilled on-scene resuscitation."},
  {"id":"pedsa1-4-4","src":"p1","num":"4.4","kind":"sba","block":"Block 4 · Accidents and Poisoning 7 QUESTIONS","page":26,"stem":"Activated charcoal is INEFFECTIVE for which of the following?","options":["Paracetamol","Tricyclic antidepressants","Iron","Aspirin","Carbamazepine"],"answer":2,"keyLetter":"C","explanation":"Charcoal does not adsorb iron, hydrocarbons or pesticides, and is only useful within 1 hour of ingestion. Gastric lavage and induced vomiting are no longer recommended."},
  {"id":"pedsa1-4-5","src":"p1","num":"4.5","kind":"sba","block":"Block 4 · Accidents and Poisoning 7 QUESTIONS","page":26,"stem":"Blood levels guide acute management in poisoning with all of the following EXCEPT:","options":["Paracetamol","Iron","Salicylate","Alcohol","Amitriptyline"],"answer":4,"keyLetter":"E","explanation":"Only paracetamol, iron, salicylate and alcohol levels are helpful acutely. Tricyclic poisoning is managed on the ECG (broad QRS → sodium bicarbonate), not on a level. A urine toxicology screen does not guide acute treatment."},
  {"id":"pedsa1-4-6","src":"p1","num":"4.6","kind":"sba","block":"Block 4 · Accidents and Poisoning 7 QUESTIONS","page":27,"stem":"A 16-year-old took 25 paracetamol tablets 6 hours ago and looks completely well. What is the most appropriate management?","options":["Discharge with advice","Activated charcoal","Paracetamol level, N-acetylcysteine as indicated, and mental health assessment","Gastric lavage","Urine toxicology screen and observation"],"answer":2,"keyLetter":"C","explanation":"Paracetamol poisoning is silent for the first 24 hours; hepatic failure appears at 3–4 days. Charcoal is useless after an hour. Deliberate self-harm always needs CAMHS assessment before discharge."},
  {"id":"pedsa1-4-7","src":"p1","num":"4.7","kind":"sba","block":"Block 4 · Accidents and Poisoning 7 QUESTIONS","page":27,"stem":"A 2-year-old is drowsy after drinking from a bottle at a party. Pupils are normal, breathing is adequate. What must be checked first?","options":["Blood alcohol level","Blood glucose","Urine toxicology","Liver function tests","ECG"],"answer":1,"keyLetter":"B","explanation":"Alcohol causes hypoglycaemia in young children, which is what harms the brain. \"Don't Ever Forget Glucose\" applies to every drowsy child."},
  {"id":"pedsa1-5-1","src":"p1","num":"5.1","kind":"sba","block":"Block 5 · Paediatric Emergencies 13 QUESTIONS","page":28,"stem":"Cardiopulmonary arrest in children is most often secondary to:","options":["Ischaemic heart disease","Primary arrhythmia","Hypoxia from respiratory failure, or shock","Electrolyte disturbance","Congenital heart disease"],"answer":2,"keyLetter":"C","explanation":"This single fact explains why paediatric basic life support begins with 5 rescue breaths and why early recognition of respiratory and circulatory failure saves lives."},
  {"id":"pedsa1-5-2","src":"p1","num":"5.2","kind":"sba","block":"Block 5 · Paediatric Emergencies 13 QUESTIONS","page":28,"stem":"Where should the brachial pulse be used to check for a pulse?","options":["In all children","In infants under 1 year","In children over 1 year","Only in the newborn","Only when the carotid is impalpable"],"answer":1,"keyLetter":"B","explanation":"Under 1 year: brachial or femoral. Over 1 year: carotid or femoral. Check for a maximum of 10 seconds."},
  {"id":"pedsa1-5-3","src":"p1","num":"5.3","kind":"sba","block":"Block 5 · Paediatric Emergencies 13 QUESTIONS","page":29,"stem":"A 3-year-old with severe asthma has become quiet and drowsy, with a falling respiratory rate and a silent chest. What does this indicate?","options":["He is improving","He is exhausted and needs urgent intubation and ventilation","He needs a further nebuliser and reassessment in an hour","He has a pneumothorax","He should be discharged after observation"],"answer":1,"keyLetter":"B","explanation":"Cyanosis, exhaustion, reduced conscious level, saturation <92% on oxygen and a rising pCO₂ define severe respiratory failure. A quietening chest is loss of air movement, not improvement."},
  {"id":"pedsa1-5-4","src":"p1","num":"5.4","kind":"sba","block":"Block 5 · Paediatric Emergencies 13 QUESTIONS","page":29,"stem":"Which is the EARLIEST reliable sign of shock in a child?","options":["Hypotension","Bradycardia","Tachycardia with prolonged capillary refill","Absent urine output","Kussmaul breathing"],"answer":2,"keyLetter":"C","explanation":"Hypotension is LATE and means compensation is failing. Bradycardia, acidotic breathing, anuria and confusion are all features of decompensated, potentially irreversible shock."},
  {"id":"pedsa1-5-5","src":"p1","num":"5.5","kind":"sba","block":"Block 5 · Paediatric Emergencies 13 QUESTIONS","page":29,"stem":"A 10 kg child in septic shock has had 40 ml/kg of fluid with limited improvement. What should be anticipated?","options":["Discharge once the heart rate settles","The need for mechanical ventilation and intensive care","Stopping antibiotics as the cultures are pending","Switching to oral rehydration","Immediate exchange transfusion"],"answer":1,"keyLetter":"B","explanation":"Children needing more than 40 ml/kg of resuscitation fluid are likely to require ventilation. Inotropes may also be needed because inflammatory mediators depress myocardial contractility."},
  {"id":"pedsa1-5-6","src":"p1","num":"5.6","kind":"sba","block":"Block 5 · Paediatric Emergencies 13 QUESTIONS","page":30,"stem":"A child with meningococcal sepsis develops widespread bruising with prolonged clotting times and a falling platelet count. What has happened?","options":["Immune thrombocytopenia","Disseminated intravascular coagulation","Haemolytic uraemic syndrome","Vitamin K deficiency","Aplastic crisis"],"answer":1,"keyLetter":"B","explanation":"Widespread inflammation → microvascular thrombosis consuming platelets and clotting factors. Correct with fresh frozen plasma, cryoprecipitate and platelets, guided by a haematologist."},
  {"id":"pedsa1-5-7","src":"p1","num":"5.7","kind":"sba","block":"Block 5 · Paediatric Emergencies 13 QUESTIONS","page":30,"stem":"An AVPU score of \"P\" in a sick child means:","options":["The child is alert","The child is stable and can be observed on the ward","The airway is at risk and will need to be maintained","The child has meningitis","The blood glucose is normal"],"answer":2,"keyLetter":"C","explanation":"\"P\" (responds only to pain) is roughly equivalent to GCS ≤8. Reduced consciousness itself destabilises the airway — and some causes are immediately reversible, above all hypoglycaemia and opiate toxicity."},
  {"id":"pedsa1-5-8","src":"p1","num":"5.8","kind":"sba","block":"Block 5 · Paediatric Emergencies 13 QUESTIONS","page":30,"stem":"A comatose child has a unilaterally dilated pupil. What does this suggest?","options":["Opiate toxicity","Hypothermia","An expanding ipsilateral lesion with uncal herniation","A pontine lesion","Post-ictal state"],"answer":2,"keyLetter":"C","explanation":"A neurosurgical emergency. Pinpoint fixed pupils = opiates or a pontine lesion; bilaterally fixed and dilated = severe hypoxia, hypothermia, post-ictal or anticholinergics."},
  {"id":"pedsa1-5-9","src":"p1","num":"5.9","kind":"sba","block":"Block 5 · Paediatric Emergencies 13 QUESTIONS","page":31,"stem":"Which is NOT part of neuroprotective management of raised intracranial pressure?","options":["Head midline and tilted 20–30°","Maintaining normothermia","Osmotic diuretics such as mannitol","Deliberate hypercapnia","Intubation and ventilation if GCS <9"],"answer":3,"keyLetter":"D","explanation":"Aim for normocapnia (PaCO₂ 4.5–5.3 kPa). Hypercapnia causes cerebral vasodilatation and raises ICP further."},
  {"id":"pedsa1-5-10","src":"p1","num":"5.10","kind":"sba","block":"Block 5 · Paediatric Emergencies 13 QUESTIONS","page":31,"stem":"A child has been fitting for 20 minutes and has already had two doses of benzodiazepine. Glucose is normal. What is the next step?","options":["A third dose of benzodiazepine","IV phenytoin over 20 minutes","Rapid sequence induction with thiopental","IV dextrose","Rectal paraldehyde alone and wait"],"answer":1,"keyLetter":"B","explanation":"A maximum of two benzodiazepine doses. Phenytoin is step 3 (phenobarbitone if already on phenytoin). Thiopental with an anaesthetist present is step 4, at about 45 minutes."},
  {"id":"pedsa1-5-11","src":"p1","num":"5.11","kind":"sba","block":"Block 5 · Paediatric Emergencies 13 QUESTIONS","page":31,"stem":"A 6-year-old collapses at a party with stridor, wheeze and urticaria after eating a biscuit. What is the first treatment?","options":["IV hydrocortisone","Nebulised adrenaline","IM adrenaline into the anterolateral thigh","IV chlorphenamine","IV fluid bolus"],"answer":2,"keyLetter":"C","explanation":"Lie the child flat with legs raised and give IM adrenaline, repeated every 5 minutes. Antihistamines and steroids are adjuncts, not treatment. Never sit a hypotensive anaphylactic patient up."},
  {"id":"pedsa1-5-12","src":"p1","num":"5.12","kind":"sba","block":"Block 5 · Paediatric Emergencies 13 QUESTIONS","page":32,"stem":"Which infant does NOT meet the criteria for a low-risk BRUE?","options":["Age 3 months","Born at 34 weeks' gestation","First such event","Event lasting 30 seconds","CPR given by a trained provider"],"answer":4,"keyLetter":"E","explanation":"Low-risk criteria: age >60 days, born ≥32 weeks, first event, lasting <1 minute, no CPR by a trained provider, and no concerning features. Failing any one makes it higher risk and requires investigation."},
  {"id":"pedsa1-5-13","src":"p1","num":"5.13","kind":"sba","block":"Block 5 · Paediatric Emergencies 13 QUESTIONS","page":32,"stem":"Which advice most reduces the risk of sudden infant death syndrome?","options":["Sleeping the baby prone to prevent aspiration","Sleeping the baby supine, feet to the foot of the cot, in the parents' room","Keeping the room at 24 °C","Using a soft pillow and duvet","Bed-sharing on a sofa for closeness"],"answer":1,"keyLetter":"B","explanation":"\"Back to sleep\" reduced SIDS from 1.9 to 0.3 per 1000 live births in the UK. Peak age 2–4 months; other advice — smoke-free, head uncovered, room about 18 °C, never sleep with the baby on a sofa or armchair, and breastfeed."},
  {"id":"pedsa1-6-1","src":"p1","num":"6.1","kind":"sba","block":"Block 6 · Perinatal Medicine 14 QUESTIONS","page":33,"stem":"How is the perinatal mortality rate defined?","options":["Deaths in the first 4 weeks per 1000 live births","Stillbirths plus deaths in the first week per 1000 live births and stillbirths","Deaths under 1 year per 1000 live births","Stillbirths per 1000 pregnancies","Deaths in the first 24 hours per 1000 deliveries"],"answer":1,"keyLetter":"B","explanation":"Option A is the neonatal mortality rate. A stillbirth is an infant born with no signs of life after 24 weeks."},
  {"id":"pedsa1-6-2","src":"p1","num":"6.2","kind":"sba","block":"Block 6 · Perinatal Medicine 14 QUESTIONS","page":33,"stem":"Which drug should not be prescribed to females of child-bearing age because of a 10% risk of congenital anomaly and a 30–40% risk of developmental delay?","options":["Carbamazepine","Sodium valproate","Lamotrigine","Levetiracetam","Phenytoin"],"answer":1,"keyLetter":"B","explanation":"Other named teratogens in your notes are retinoids and warfarin. Women on anticonvulsants also need a higher dose of folic acid."},
  {"id":"pedsa1-6-3","src":"p1","num":"6.3","kind":"sba","block":"Block 6 · Perinatal Medicine 14 QUESTIONS","page":34,"stem":"A 20-week scan shows severe oligohydramnios. Which fetal abnormality is most likely to be responsible?","options":["Duodenal atresia","Oesophageal atresia","Bilateral renal dysplasia","Anencephaly","Exomphalos"],"answer":2,"keyLetter":"C","explanation":"Amniotic fluid is fetal urine. Too little → renal problem, obstructive uropathy or ruptured membranes, leading to pulmonary hypoplasia and Potter sequence. Atresias cause polyhydramnios because the fetus cannot swallow."},
  {"id":"pedsa1-6-4","src":"p1","num":"6.4","kind":"sba","block":"Block 6 · Perinatal Medicine 14 QUESTIONS","page":34,"stem":"Antenatal corticosteroids are given before anticipated preterm delivery. For optimal effect, the completed course should be given:","options":["At any time in the preceding month","At least 24 hours before delivery and within 1–7 days of birth","Within 2 hours of delivery","Only after the membranes rupture","Only after 34 weeks' gestation"],"answer":1,"keyLetter":"B","explanation":"They accelerate lung maturity and surfactant production and reduce RDS, intraventricular haemorrhage and neonatal mortality."},
  {"id":"pedsa1-6-5","src":"p1","num":"6.5","kind":"sba","block":"Block 6 · Perinatal Medicine 14 QUESTIONS","page":34,"stem":"Fetal anaemia from rhesus isoimmunisation is detected non-invasively by:","options":["Amniocentesis","Doppler velocimetry of the fetal middle cerebral artery","Cordocentesis","Maternal haemoglobin measurement","Fetal MRI"],"answer":1,"keyLetter":"B","explanation":"Severely affected fetuses may need intrauterine transfusion via the umbilical vein from about 20 weeks."},
  {"id":"pedsa1-6-6","src":"p1","num":"6.6","kind":"sba","block":"Block 6 · Perinatal Medicine 14 QUESTIONS","page":35,"stem":"Which congenital malformation is characteristically associated with maternal diabetes?","options":["Tracheo-oesophageal fistula","Sacral agenesis","Duodenal atresia","Diaphragmatic hernia","Cleft palate"],"answer":1,"keyLetter":"B","explanation":"Sacral agenesis (caudal regression) is rare but characteristic; cardiac malformations are the commonest. Overall malformation risk is 6% — four times background — and is reduced by good periconceptional control."},
  {"id":"pedsa1-6-7","src":"p1","num":"6.7","kind":"sba","block":"Block 6 · Perinatal Medicine 14 QUESTIONS","page":35,"stem":"A 4.4 kg infant of a diabetic mother is jittery at 90 minutes of age. What is the mechanism?","options":["Hypocalcaemia from poor stores","Persisting fetal hyperinsulinism after the placental glucose supply stops","Glycogen storage disease","Adrenal insufficiency","Hypothermia alone"],"answer":1,"keyLetter":"B","explanation":"Maternal hyperglycaemia → fetal hyperglycaemia → islet cell hyperplasia and high insulin, which persists after birth. Prevented by early feeding and close glucose monitoring for 24 hours."},
  {"id":"pedsa1-6-8","src":"p1","num":"6.8","kind":"sba","block":"Block 6 · Perinatal Medicine 14 QUESTIONS","page":35,"stem":"Maternal rubella infection at 6 weeks' gestation carries a risk of cataracts, deafness and congenital heart disease of approximately:","options":["5%","20%","50%","Over 80%","Minimal"],"answer":3,"keyLetter":"D","explanation":"Before 8 weeks >80%; at 13–16 weeks about 30% have impaired hearing; beyond 18 weeks the risk is minimal. Congenital rubella is entirely preventable by immunisation."},
  {"id":"pedsa1-6-9","src":"p1","num":"6.9","kind":"sba","block":"Block 6 · Perinatal Medicine 14 QUESTIONS","page":36,"stem":"Which is the most common congenital infection and the commonest non-genetic cause of sensorineural hearing loss?","options":["Rubella","Toxoplasmosis","Cytomegalovirus","Syphilis","Parvovirus B19"],"answer":2,"keyLetter":"C","explanation":"Of infected infants, 90% are normal at birth, 5% have features at birth (hepatosplenomegaly, petechiae) and 5% develop later problems, mainly deafness."},
  {"id":"pedsa1-6-10","src":"p1","num":"6.10","kind":"sba","block":"Block 6 · Perinatal Medicine 14 QUESTIONS","page":36,"stem":"A newborn has chorioretinitis, hydrocephalus and intracranial calcification. The mother ate undercooked meat during pregnancy. What is the treatment?","options":["Ganciclovir for 6 weeks","Pyrimethamine and sulfadiazine for 1 year","Benzylpenicillin for 10 days","Aciclovir for 3 weeks","No treatment is available"],"answer":1,"keyLetter":"B","explanation":"Congenital toxoplasmosis. About 40% of fetuses are infected during a primary maternal parasitaemia; most infected infants are asymptomatic but remain at risk of chorioretinitis into adulthood."},
  {"id":"pedsa1-6-11","src":"p1","num":"6.11","kind":"sba","block":"Block 6 · Perinatal Medicine 14 QUESTIONS","page":36,"stem":"Why is transient tachypnoea more common after elective caesarean section?","options":["The baby is usually preterm","There is no maternal catecholamine surge and no squeezing of the chest in the birth canal","Surfactant production is reduced by anaesthesia","The cord is clamped too late","Maternal antibodies are not transferred"],"answer":1,"keyLetter":"B","explanation":"Both mechanisms normally clear lung fluid. Chest X-ray classically shows fluid in the horizontal fissure, and it is self-limiting."},
  {"id":"pedsa1-6-12","src":"p1","num":"6.12","kind":"sba","block":"Block 6 · Perinatal Medicine 14 QUESTIONS","page":37,"stem":"What is the first step in newborn resuscitation?","options":["Suction the airway","Give 5 inflation breaths","Dry the baby and keep it warm","Start chest compressions","Give adrenaline"],"answer":2,"keyLetter":"C","explanation":"Dry, remove wet towels, keep warm (36.5–37.5 °C) and start the clock. Routine suction is avoided — it provokes vagal bradycardia. The whole goal of newborn resuscitation is lung aeration."},
  {"id":"pedsa1-6-13","src":"p1","num":"6.13","kind":"sba","block":"Block 6 · Perinatal Medicine 14 QUESTIONS","page":37,"stem":"After 5 inflation breaths and 30 seconds of effective ventilation with good chest movement, a newborn's heart rate is 45/min. What is the next step?","options":["Repeat the inflation breaths","Chest compressions at 3 : 1 with ventilation and increase oxygen to 100%","Give IV sodium bicarbonate","Stop resuscitation","Give a 20 ml/kg fluid bolus"],"answer":1,"keyLetter":"B","explanation":"Compressions start when the heart rate is <60/min despite effective ventilation: 90 compressions to 30 breaths (120 events/min), stopping compressions once the rate exceeds 60. Note the ratio is 3 : 1, not 15 : 2."},
  {"id":"pedsa1-6-14","src":"p1","num":"6.14","kind":"sba","block":"Block 6 · Perinatal Medicine 14 QUESTIONS","page":37,"stem":"Which condition is screened for by the newborn blood spot test taken on day 5?","options":["Developmental dysplasia of the hip","Congenital cataract","Medium-chain acyl-CoA dehydrogenase (MCAD) deficiency","Congenital heart disease","Hearing loss"],"answer":2,"keyLetter":"C","explanation":"The blood spot screens for congenital hypothyroidism, haemoglobinopathies, cystic fibrosis and six inherited metabolic diseases (PKU, MCAD, maple syrup urine disease, isovaleric acidaemia, glutaric aciduria type 1, homocystinuria). DDH and cataract are found on clinical examination."},
  {"id":"pedsa1-7-1","src":"p1","num":"7.1","kind":"sba","block":"Block 7 · Neonatal Medicine 18 QUESTIONS · HIGHEST WEIGHT","page":38,"stem":"Surfactant is produced by which cells?","options":["Type I pneumocytes","Type II pneumocytes","Alveolar macrophages","Clara cells","Bronchial goblet cells"],"answer":1,"keyLetter":"B","explanation":"A mixture of phospholipids and proteins that lowers alveolar surface tension. Deficiency → widespread alveolar collapse."},
  {"id":"pedsa1-7-2","src":"p1","num":"7.2","kind":"sba","block":"Block 7 · Neonatal Medicine 18 QUESTIONS · HIGHEST WEIGHT","page":38,"stem":"Which chest X-ray appearance is characteristic of respiratory distress syndrome?","options":["Fluid in the horizontal fissure","Diffuse ground-glass appearance with an air bronchogram","Over-inflation with patchy consolidation","Bowel loops in the left hemithorax","Normal lung fields with a small heart"],"answer":1,"keyLetter":"B","explanation":"With an indistinct heart border. Option A is TTN, C is meconium aspiration, D is a diaphragmatic hernia and E fits PPHN or cyanotic heart disease."},
  {"id":"pedsa1-7-3","src":"p1","num":"7.3","kind":"sba","block":"Block 7 · Neonatal Medicine 18 QUESTIONS · HIGHEST WEIGHT","page":39,"stem":"What is the target oxygen saturation range for a preterm infant?","options":["85–90%","91–95%","96–100%","Above 98%","Any value above 88%"],"answer":1,"keyLetter":"B","explanation":"Below 91% increases necrotising enterocolitis and death; above 95% increases retinopathy of prematurity. Excess oxygen damages lungs, brain and eyes through free radicals."},
  {"id":"pedsa1-7-4","src":"p1","num":"7.4","kind":"sba","block":"Block 7 · Neonatal Medicine 18 QUESTIONS · HIGHEST WEIGHT","page":39,"stem":"A ventilated preterm infant with RDS suddenly needs more oxygen. Breath sounds and chest movement are reduced on the right. Which bedside test can confirm the diagnosis fastest?","options":["Blood gas","Transillumination with a fibre-optic light","Echocardiography","Cranial ultrasound","Blood culture"],"answer":1,"keyLetter":"B","explanation":"Pneumothorax complicates up to 10% of infants ventilated for RDS. Confirm with transillumination, lung ultrasound or chest X-ray; treat by aspiration and chest drain."},
  {"id":"pedsa1-7-5","src":"p1","num":"7.5","kind":"sba","block":"Block 7 · Neonatal Medicine 18 QUESTIONS · HIGHEST WEIGHT","page":39,"stem":"A 28-week infant has recurrent apnoea with bradycardia. Sepsis, anaemia and electrolyte disturbance have been excluded. Which treatment is indicated?","options":["Caffeine","Phenobarbitone","Aminophylline nebulisers","Surfactant","Ibuprofen"],"answer":0,"keyLetter":"A","explanation":"Apnoea of prematurity reflects immaturity of central respiratory control and resolves by about 32 weeks. Caffeine helps and improves long-term outcomes."},
  {"id":"pedsa1-7-6","src":"p1","num":"7.6","kind":"sba","block":"Block 7 · Neonatal Medicine 18 QUESTIONS · HIGHEST WEIGHT","page":40,"stem":"A 26-week infant on day 12, recently established on formula feeds, has abdominal distension, bile-stained aspirates and blood in the stool. Which X-ray finding is characteristic?","options":["Double bubble","Intramural gas (pneumatosis intestinalis) and portal venous gas","Ground-glass lungs","Absent rectal gas only","Multiple air-fluid levels alone"],"answer":1,"keyLetter":"B","explanation":"Necrotising enterocolitis — mortality about 20%. Breast milk is protective; formula, rapid feed increases and antibiotics adversely affect the gut microbiome. Stop feeds, give antibiotics and parenteral nutrition; operate for perforation."},
  {"id":"pedsa1-7-7","src":"p1","num":"7.7","kind":"sba","block":"Block 7 · Neonatal Medicine 18 QUESTIONS · HIGHEST WEIGHT","page":40,"stem":"Intraventricular haemorrhage in preterm infants arises from which site, and when?","options":["The choroid plexus, in the second week","The germinal matrix, within the first 72 hours","The subarachnoid space, at delivery","The dural sinuses, after a month","The cerebellum, at 2 weeks"],"answer":1,"keyLetter":"B","explanation":"The germinal matrix above the caudate nucleus contains a fragile vascular network. Risk factors: perinatal asphyxia, severe RDS, pneumothorax. Antenatal steroids reduce both RDS and IVH."},
  {"id":"pedsa1-7-8","src":"p1","num":"7.8","kind":"sba","block":"Block 7 · Neonatal Medicine 18 QUESTIONS · HIGHEST WEIGHT","page":41,"stem":"Bilateral posterior periventricular cysts on cranial ultrasound carry an 80–90% risk of which outcome?","options":["Hemiplegia","Spastic diplegia","Deafness","Hydrocephalus","Blindness"],"answer":1,"keyLetter":"B","explanation":"Periventricular leukomalacia → spastic diplegia, often with cognitive impairment. A unilateral parenchymal haemorrhagic infarct causes hemiplegia. Both PVL and IVH can occur with no abnormal clinical signs."},
  {"id":"pedsa1-7-9","src":"p1","num":"7.9","kind":"sba","block":"Block 7 · Neonatal Medicine 18 QUESTIONS · HIGHEST WEIGHT","page":41,"stem":"Bronchopulmonary dysplasia is defined as:","options":["Oxygen requirement at 28 days of age","Oxygen requirement at 36 weeks' post-menstrual age","Ventilation for more than 7 days","Any preterm with an abnormal chest X-ray","Persistent wheeze at discharge"],"answer":1,"keyLetter":"B","explanation":"Caused by delayed lung maturation, pressure/volume trauma, oxygen toxicity and infection. Corticosteroids help weaning but are restricted to short, low-dose courses because of neurodevelopmental concerns."},
  {"id":"pedsa1-7-10","src":"p1","num":"7.10","kind":"sba","block":"Block 7 · Neonatal Medicine 18 QUESTIONS · HIGHEST WEIGHT","page":42,"stem":"A term infant develops cyanosis soon after birth with only mild respiratory distress. The chest X-ray shows a normal-sized heart and pulmonary oligaemia, and no murmur is heard. What is the most appropriate next investigation?","options":["Repeat chest X-ray in 6 hours","Urgent echocardiography","Cranial ultrasound","Blood culture only","Sweat test"],"answer":1,"keyLetter":"B","explanation":"The echo distinguishes PPHN (raised pulmonary pressures, tricuspid regurgitation, right-to-left shunting) from cyanotic congenital heart disease. PPHN is treated with ventilation, inhaled nitric oxide, and if needed HFOV or ECMO."},
  {"id":"pedsa1-7-11","src":"p1","num":"7.11","kind":"sba","block":"Block 7 · Neonatal Medicine 18 QUESTIONS · HIGHEST WEIGHT","page":42,"stem":"A term baby is visibly jaundiced at 10 hours of age. What is the most likely mechanism?","options":["Physiological jaundice","Breast milk jaundice","Haemolysis","Biliary atresia","Congenital hypothyroidism"],"answer":2,"keyLetter":"C","explanation":"Jaundice within 24 hours is always abnormal — rhesus or ABO incompatibility, G6PD deficiency, spherocytosis, or congenital infection. It needs urgent investigation and close monitoring."},
  {"id":"pedsa1-7-12","src":"p1","num":"7.12","kind":"sba","block":"Block 7 · Neonatal Medicine 18 QUESTIONS · HIGHEST WEIGHT","page":43,"stem":"Which statement about ABO haemolytic disease is correct?","options":["It is less common than rhesus haemolytic disease","Hepatosplenomegaly is characteristic","It usually affects a group A infant of a group O mother, peaking at 12–72 hours","The haemoglobin is always severely reduced","The direct antiglobulin test is negative"],"answer":2,"keyLetter":"C","explanation":"ABO incompatibility is now more common than rhesus disease. Jaundice is usually less severe, there is no hepatosplenomegaly, and the haemoglobin is normal or only slightly reduced."},
  {"id":"pedsa1-7-13","src":"p1","num":"7.13","kind":"sba","block":"Block 7 · Neonatal Medicine 18 QUESTIONS · HIGHEST WEIGHT","page":43,"stem":"A breastfed baby is still jaundiced at 3 weeks. His stools are pale and his urine stains the nappy dark. What is the priority?","options":["Reassure — breast milk jaundice can last 12 weeks","Measure the split bilirubin urgently","Start phototherapy","Stop breastfeeding for 48 hours","Check thyroid function only"],"answer":1,"keyLetter":"B","explanation":"Pale stools and dark urine mean conjugated hyperbilirubinaemia — biliary atresia until proven otherwise. The prognosis of the Kasai portoenterostomy depends on early diagnosis."},
  {"id":"pedsa1-7-14","src":"p1","num":"7.14","kind":"sba","block":"Block 7 · Neonatal Medicine 18 QUESTIONS · HIGHEST WEIGHT","page":43,"stem":"Kernicterus results from deposition of which substance, and where?","options":["Conjugated bilirubin in the liver","Unconjugated bilirubin in the basal ganglia and brainstem nuclei","Conjugated bilirubin in the cerebral cortex","Urobilinogen in the kidney","Haemosiderin in the choroid plexus"],"answer":1,"keyLetter":"B","explanation":"Unconjugated bilirubin is lipid-soluble and crosses the blood–brain barrier when albumin binding is saturated. Acute: lethargy, opisthotonos, seizures. Survivors: choreoathetoid cerebral palsy and sensorineural deafness."},
  {"id":"pedsa1-7-15","src":"p1","num":"7.15","kind":"sba","block":"Block 7 · Neonatal Medicine 18 QUESTIONS · HIGHEST WEIGHT","page":44,"stem":"Which organisms most commonly cause early-onset (<72 hours) neonatal sepsis?","options":["Coagulase-negative staphylococcus and Candida","Group B streptococcus and E. coli","Staphylococcus aureus and Pseudomonas","Neisseria meningitidis and pneumococcus","Mycoplasma and Chlamydia"],"answer":1,"keyLetter":"B","explanation":"Treated with benzylpenicillin or ampicillin plus gentamicin. Option A is the profile of late-onset (nosocomial) sepsis."},
  {"id":"pedsa1-7-16","src":"p1","num":"7.16","kind":"sba","block":"Block 7 · Neonatal Medicine 18 QUESTIONS · HIGHEST WEIGHT","page":44,"stem":"A newborn has a septic screen for risk factors. The first CRP at 4 hours is normal. What is the correct interpretation?","options":["Infection is excluded; stop antibiotics now","CRP takes 12–24 hours to rise, so one normal value does not exclude infection","CRP is not useful in neonates at all","A normal CRP means the blood culture will be negative","Antibiotics must continue for 7 days regardless"],"answer":1,"keyLetter":"B","explanation":"Two consecutive normal values are strong evidence against infection, allowing antibiotics to be stopped at 36–48 hours if cultures are negative and the baby is well."},
  {"id":"pedsa1-7-17","src":"p1","num":"7.17","kind":"sba","block":"Block 7 · Neonatal Medicine 18 QUESTIONS · HIGHEST WEIGHT","page":45,"stem":"A term infant born after placental abruption is hypotonic with seizures at 3 hours of age. Which intervention improves outcome?","options":["Prophylactic phenobarbitone","Therapeutic hypothermia to 33–34 °C for 72 hours, started within 6 hours","Warming to 38 °C","High-dose corticosteroids","Hyperventilation to a PaCO₂ of 3.5 kPa"],"answer":1,"keyLetter":"B","explanation":"Moderate or severe HIE in an infant ≥36 weeks. Cooling works by interrupting delayed (reperfusion) neuronal death — hence the 6-hour window. NNT 8; it reduces death and cerebral palsy but not seizures. Hyperthermia must be avoided."},
  {"id":"pedsa1-7-18","src":"p1","num":"7.18","kind":"sba","block":"Block 7 · Neonatal Medicine 18 QUESTIONS · HIGHEST WEIGHT","page":45,"stem":"A newborn has a scalp swelling that does not cross the suture lines and feels soft in the centre. What is it?","options":["Caput succedaneum","Cephalhaematoma","Subaponeurotic (subgaleal) haemorrhage","Chignon","Encephalocele"],"answer":1,"keyLetter":"B","explanation":"Bleeding below the periosteum, confined to one bone (usually parietal), resolving over weeks. Caput crosses sutures and clears in days; a diffuse boggy swelling of the whole scalp is a subgaleal haemorrhage and can cause hypovolaemic shock and coagulopathy."},
  {"id":"pedsa1-8-1","src":"p1","num":"8.1","kind":"sba","block":"Block 8 · Allergy 8 QUESTIONS","page":46,"stem":"A 5-year-old has a positive skin-prick test to peanut but eats peanut butter regularly with no symptoms. What is the correct term?","options":["Peanut allergy","Sensitisation to peanut","Anaphylaxis risk","Atopy","Food intolerance"],"answer":1,"keyLetter":"B","explanation":"Sensitisation is a positive test; allergy is a positive test PLUS a clinical reaction. He must not be told to avoid peanut — that would risk losing tolerance."},
  {"id":"pedsa1-8-2","src":"p1","num":"8.2","kind":"sba","block":"Block 8 · Allergy 8 QUESTIONS","page":46,"stem":"Why must a child be observed in hospital for several hours after a moderate or severe food allergy reaction?","options":["Because adrenaline wears off in 30 minutes","Because of the late-phase response 4–6 hours after exposure","To complete a food challenge","To measure the specific IgE","Because antihistamines take 6 hours to work"],"answer":1,"keyLetter":"B","explanation":"Early phase = minutes, mast cell histamine. Late phase = 4–6 hours, cellular inflammation — the reaction can return."},
  {"id":"pedsa1-8-3","src":"p1","num":"8.3","kind":"sba","block":"Block 8 · Allergy 8 QUESTIONS","page":47,"stem":"Which wheal size is regarded as a positive skin-prick test, and when is it read?","options":["2 mm at 5 minutes","4 mm or more at 15 minutes","10 mm at 20 minutes","Any erythema at 30 minutes","5 mm at 48 hours"],"answer":1,"keyLetter":"B","explanation":"Antihistamines must be stopped 48–72 hours beforehand. Remember that neither the wheal size nor the IgE level predicts the severity of a reaction."},
  {"id":"pedsa1-8-4","src":"p1","num":"8.4","kind":"sba","block":"Block 8 · Allergy 8 QUESTIONS","page":47,"stem":"Which strategy has been shown to REDUCE the development of food allergy?","options":["Delaying peanut and egg until 3 years of age","Early introduction of egg and peanut in infancy","Maternal avoidance of nuts during breastfeeding","Routine probiotic supplementation","Regular emollient use from birth"],"answer":1,"keyLetter":"B","explanation":"Inducing immune tolerance. Probiotics, prebiotics, omega-3, vitamin D, antihistamines and moisturisers have all been tried without success. Delaying allergens is the old, reversed advice."},
  {"id":"pedsa1-8-5","src":"p1","num":"8.5","kind":"sba","block":"Block 8 · Allergy 8 QUESTIONS","page":47,"stem":"A 4-month-old formula-fed infant has loose stools, blood-streaked at times, and faltering growth. The skin-prick test to cow's milk is negative. Symptoms resolve on an extensively hydrolysed formula and recur on reintroduction. What is the diagnosis?","options":["Lactose intolerance","IgE-mediated cow's milk allergy","Non-IgE-mediated cow's milk protein allergy","Coeliac disease","Infective colitis"],"answer":2,"keyLetter":"C","explanation":"A negative skin-prick test excludes only the IgE-mediated form. Non-IgE disease is gastrointestinal, delayed by hours, tests negative, and is diagnosed by elimination and reintroduction."},
  {"id":"pedsa1-8-6","src":"p1","num":"8.6","kind":"sba","block":"Block 8 · Allergy 8 QUESTIONS","page":48,"stem":"A child with egg allergy reacts to lightly cooked egg but tolerates cake containing egg. What is the explanation?","options":["He has outgrown the allergy","Heating to high temperatures degrades the allergenic proteins","The cake contains a different species of egg","Sugar blocks histamine release","He has a non-IgE-mediated allergy"],"answer":1,"keyLetter":"B","explanation":"Heat degradation and food processing reduce allergenicity — the same applies to baked milk. This is flagged as an MCQ point in your notes."},
  {"id":"pedsa1-8-7","src":"p1","num":"8.7","kind":"sba","block":"Block 8 · Allergy 8 QUESTIONS","page":48,"stem":"A 9-year-old has had urticaria almost daily for 4 months. There is no consistent trigger. What is the most likely situation?","options":["Undiagnosed food allergy — send a broad allergy panel","Chronic urticaria, which is usually non-allergic","Hereditary angioedema","Mastocytosis","Drug allergy"],"answer":1,"keyLetter":"B","explanation":"Allergic urticaria appears within 1 hour, is reproducible on every exposure and resolves within 2–4 hours. Chronic urticaria (>6 weeks) is usually non-allergic; treat with non-sedating antihistamines, at higher than standard dose if needed."},
  {"id":"pedsa1-8-8","src":"p1","num":"8.8","kind":"sba","block":"Block 8 · Allergy 8 QUESTIONS","page":49,"stem":"A child has recurrent episodes of lip and tongue swelling with NO urticaria, unresponsive to antihistamines and adrenaline. What should be considered?","options":["Peanut allergy","C1 esterase inhibitor deficiency","Idiopathic anaphylaxis","Chronic urticaria","Papular urticaria"],"answer":1,"keyLetter":"B","explanation":"Angioedema WITHOUT urticaria is the classic pointer to hereditary angioedema, which does not respond to adrenaline, steroids or antihistamines and needs specialist review."},
  {"id":"pedsa1-9-1","src":"p1","num":"9.1","kind":"sba","block":"Block 9 · Infection and Immunity 24 QUESTIONS · HIGHEST WEIGHT","page":50,"stem":"A 6-week-old has a temperature of 38.4 °C and no focus of infection. What is the correct management?","options":["Paracetamol and review in 24 hours","Oral antibiotics at home","Full septic screen and immediate broad-spectrum IV antibiotics","Urine dipstick only","Reassure — the height of fever is what matters"],"answer":2,"keyLetter":"C","explanation":"Infants under 3 months present non-specifically and bacterial infection cannot be excluded clinically. \"The younger the child, the lower the threshold for a septic screen and antibiotics.\""},
  {"id":"pedsa1-9-2","src":"p1","num":"9.2","kind":"sba","block":"Block 9 · Infection and Immunity 24 QUESTIONS · HIGHEST WEIGHT","page":50,"stem":"Which statement about fever in children is correct?","options":["Fever is defined as a temperature over 37.5 °C","Axillary temperature overestimates body temperature by 0.5 °C","Antipyretics prevent febrile seizures","Parental report of fever is a valid assessment","The height of the fever predicts serious bacterial infection"],"answer":3,"keyLetter":"D","explanation":"Fever is >38.0 °C; axilla underestimates by 0.5 °C; antipyretics do not prevent febrile seizures; and it is the presence, not the height, of fever that matters."},
  {"id":"pedsa1-9-3","src":"p1","num":"9.3","kind":"sba","block":"Block 9 · Infection and Immunity 24 QUESTIONS · HIGHEST WEIGHT","page":51,"stem":"Which organisms cause bacterial meningitis in an infant under 3 months?","options":["Meningococcus and pneumococcus","Group B streptococcus, E. coli and Listeria","Haemophilus influenzae type b and Staphylococcus aureus","Mycobacterium tuberculosis and Cryptococcus","Enteroviruses only"],"answer":1,"keyLetter":"B","explanation":"Which is why amoxicillin is added to the third-generation cephalosporin under 3 months — to cover Listeria."},
  {"id":"pedsa1-9-4","src":"p1","num":"9.4","kind":"sba","block":"Block 9 · Infection and Immunity 24 QUESTIONS · HIGHEST WEIGHT","page":51,"stem":"A CSF sample is turbid, with numerous polymorphs, a high protein and a low glucose. What does it indicate?","options":["Viral meningitis","Bacterial meningitis","Tuberculous meningitis","Encephalitis","A normal sample"],"answer":1,"keyLetter":"B","explanation":"TB gives lymphocytes with a very high protein and a very low glucose; viral gives lymphocytes with normal or slightly raised protein. Two exceptions: lymphocytes can predominate in Lyme meningitis, and glucose can be low in enteroviral meningitis."},
  {"id":"pedsa1-9-5","src":"p1","num":"9.5","kind":"sba","block":"Block 9 · Infection and Immunity 24 QUESTIONS · HIGHEST WEIGHT","page":52,"stem":"All of the following are contraindications to lumbar puncture EXCEPT:","options":["Cardiorespiratory instability","Focal neurological signs","Thrombocytopenia","A purpuric rash","Local infection at the puncture site"],"answer":3,"keyLetter":"D","explanation":"A purpuric rash is a reason to give antibiotics immediately, not a contraindication in itself. The contraindications relate to coning (raised ICP, focal signs), bleeding (coagulopathy, low platelets), instability, and local infection. Never delay antibiotics for the LP."},
  {"id":"pedsa1-9-6","src":"p1","num":"9.6","kind":"sba","block":"Block 9 · Infection and Immunity 24 QUESTIONS · HIGHEST WEIGHT","page":52,"stem":"Which complication of bacterial meningitis is most strongly associated with pneumococcal infection?","options":["Subdural effusion","Cranial nerve palsy","Cerebral abscess","Limb loss","Purpura fulminans"],"answer":0,"keyLetter":"A","explanation":"Confirmed on CT or MRI. Remember also that every child after bacterial meningitis needs audiological assessment — deafness follows damage to the cochlear hair cells."},
  {"id":"pedsa1-9-7","src":"p1","num":"9.7","kind":"sba","block":"Block 9 · Infection and Immunity 24 QUESTIONS · HIGHEST WEIGHT","page":52,"stem":"Which form of bacterial meningitis has the LOWEST risk of long-term neurological sequelae?","options":["Pneumococcal","Meningococcal","Haemophilus influenzae type b","Group B streptococcal","Listeria"],"answer":1,"keyLetter":"B","explanation":"Most survivors of meningococcal meningitis recover fully — though the septicaemia can kill within hours and may cause limb loss."},
  {"id":"pedsa1-9-8","src":"p1","num":"9.8","kind":"sba","block":"Block 9 · Infection and Immunity 24 QUESTIONS · HIGHEST WEIGHT","page":53,"stem":"A GP sees a febrile 3-year-old with a spreading non-blanching rash. What should be done before transfer?","options":["Nothing — transfer immediately without treatment","Give IM benzylpenicillin","Give oral amoxicillin","Take a blood culture first","Perform a lumbar puncture"],"answer":1,"keyLetter":"B","explanation":"Any febrile child with a purpuric rash gets IM benzylpenicillin (or IV third-generation cephalosporin) immediately and urgent transfer. Meningococcal septicaemia can kill within hours."},
  {"id":"pedsa1-9-9","src":"p1","num":"9.9","kind":"sba","block":"Block 9 · Infection and Immunity 24 QUESTIONS · HIGHEST WEIGHT","page":53,"stem":"A 4-year-old has fever, seizures and altered consciousness. There are no cold sores or skin lesions. What must be started?","options":["High-dose IV aciclovir","Oral aciclovir if lesions appear","Corticosteroids","IV immunoglobulin","Antibiotics alone, pending CSF PCR"],"answer":0,"keyLetter":"A","explanation":"All children with encephalitis are treated initially with high-dose IV aciclovir until HSV is excluded — most affected children have no outward herpetic signs. Untreated HSV encephalitis has a mortality above 70%. Treat for 3 weeks if confirmed, because relapses follow shorter courses."},
  {"id":"pedsa1-9-10","src":"p1","num":"9.10","kind":"sba","block":"Block 9 · Infection and Immunity 24 QUESTIONS · HIGHEST WEIGHT","page":54,"stem":"A 6-year-old has a sore throat and a rash with a sandpaper texture that spares the skin around the mouth. His tongue is red with prominent papillae. How long should antibiotics be given?","options":["3 days","5 days","10 days","Single dose","No antibiotic is needed"],"answer":2,"keyLetter":"C","explanation":"Scarlet fever. Penicillin V shortens the illness by only about 16 hours, but the 10-day course eradicates group A streptococcus and prevents rheumatic fever and glomerulonephritis."},
  {"id":"pedsa1-9-11","src":"p1","num":"9.11","kind":"sba","block":"Block 9 · Infection and Immunity 24 QUESTIONS · HIGHEST WEIGHT","page":54,"stem":"A 4-year-old has a swollen red eyelid and fever. Eye movements are full and painless and visual acuity is normal. What is the diagnosis and management?","options":["Orbital cellulitis — urgent CT and surgery","Periorbital cellulitis — IV antibiotics to prevent orbital spread","Allergic angioedema — antihistamines","Conjunctivitis — topical chloramphenicol","Chalazion — reassurance"],"answer":1,"keyLetter":"B","explanation":"Preseptal disease. Proptosis, painful or limited eye movements, or reduced visual acuity would mean orbital cellulitis, which needs CT/MRI and ophthalmology. Complications include meningitis, abscess and cavernous sinus thrombosis."},
  {"id":"pedsa1-9-12","src":"p1","num":"9.12","kind":"sba","block":"Block 9 · Infection and Immunity 24 QUESTIONS · HIGHEST WEIGHT","page":55,"stem":"An infant has fever, erythema and skin tenderness with epidermal separation on gentle pressure. What is the diagnosis?","options":["Toxic epidermal necrolysis","Staphylococcal scalded skin syndrome","Scald from non-accidental injury","Bullous impetigo","Erythema multiforme"],"answer":1,"keyLetter":"B","explanation":"An exfoliative staphylococcal toxin separates the epidermal layers — a positive Nikolsky sign. Treat with IV anti-staphylococcal antibiotics; it heals without scarring. Its appearance must not be mistaken for a scald."},
  {"id":"pedsa1-9-13","src":"p1","num":"9.13","kind":"sba","block":"Block 9 · Infection and Immunity 24 QUESTIONS · HIGHEST WEIGHT","page":55,"stem":"A 15-month-old had 3 days of high fever. The fever has now settled and a macular rash has appeared on the trunk. He looks well. What is the diagnosis?","options":["Measles","Rubella","Roseola infantum (HHV-6/7)","Scarlet fever","Drug rash"],"answer":2,"keyLetter":"C","explanation":"The rash appears as the fever wanes. Most children are infected by 2 years. This sequence is the reason many toddlers are wrongly labelled antibiotic-allergic."},
  {"id":"pedsa1-9-14","src":"p1","num":"9.14","kind":"sba","block":"Block 9 · Infection and Immunity 24 QUESTIONS · HIGHEST WEIGHT","page":56,"stem":"A child with sickle cell disease develops sudden severe anaemia with a LOW reticulocyte count. Which infection is responsible?","options":["Parvovirus B19","Pneumococcus","Salmonella","Epstein–Barr virus","Cytomegalovirus"],"answer":0,"keyLetter":"A","explanation":"Parvovirus B19 infects erythroblastoid red cell precursors, causing an aplastic crisis — hence the low reticulocyte count. In pregnancy it can cause fetal hydrops."},
  {"id":"pedsa1-9-15","src":"p1","num":"9.15","kind":"sba","block":"Block 9 · Infection and Immunity 24 QUESTIONS · HIGHEST WEIGHT","page":56,"stem":"A 14-year-old with fever, severe tonsillitis and cervical lymphadenopathy develops a florid maculopapular rash after starting amoxicillin. What is the most likely explanation?","options":["Penicillin allergy — label him allergic for life","Infectious mononucleosis","Scarlet fever","Stevens–Johnson syndrome","Measles"],"answer":1,"keyLetter":"B","explanation":"Ampicillin and amoxicillin cause a florid rash in EBV infection and should be avoided. It is not allergy. Confirm with atypical lymphocytes and a Monospot; avoid contact sport if there is splenomegaly."},
  {"id":"pedsa1-9-16","src":"p1","num":"9.16","kind":"sba","block":"Block 9 · Infection and Immunity 24 QUESTIONS · HIGHEST WEIGHT","page":56,"stem":"Which finding best distinguishes measles from roseola?","options":["The presence of fever","The child is at his most unwell when the rash appears, with Koplik spots and conjunctivitis","The rash is maculopapular","The age of the child","The rash lasts more than 24 hours"],"answer":1,"keyLetter":"B","explanation":"In measles the rash spreads downward from behind the ears while the child is very unwell, with the 3 Cs and Koplik spots. In roseola the rash appears as the fever settles in a well child."},
  {"id":"pedsa1-9-17","src":"p1","num":"9.17","kind":"sba","block":"Block 9 · Infection and Immunity 24 QUESTIONS · HIGHEST WEIGHT","page":57,"stem":"Subacute sclerosing panencephalitis follows which infection, and after roughly how long?","options":["Mumps, after 1 year","Measles, after an average of 7 years","Rubella, after 6 months","Varicella, after 2 years","Parvovirus, after 10 years"],"answer":1,"keyLetter":"B","explanation":"About 1 in 100,000 cases; most had measles before 2 years of age. Caused by a variant virus persisting in the CNS; progressive and fatal. Acute measles encephalitis is different — 1 in 5000, a few days after the illness, mortality 15%."},
  {"id":"pedsa1-9-18","src":"p1","num":"9.18","kind":"sba","block":"Block 9 · Infection and Immunity 24 QUESTIONS · HIGHEST WEIGHT","page":57,"stem":"A 3-year-old with atopic eczema develops a rapidly spreading crop of painful vesicles on the eczematous skin, with fever. What is the treatment?","options":["Increase the topical steroid","Intravenous aciclovir","Oral flucloxacillin alone","Emollients and observation","Oral prednisolone"],"answer":1,"keyLetter":"B","explanation":"Eczema herpeticum — it may be complicated by secondary bacterial infection and septicaemia. Its lookalike, eczema coxsackium, needs no treatment, but you treat for herpes until you are sure."},
  {"id":"pedsa1-9-19","src":"p1","num":"9.19","kind":"sba","block":"Block 9 · Infection and Immunity 24 QUESTIONS · HIGHEST WEIGHT","page":58,"stem":"A 2-year-old has had fever for 6 days, is markedly irritable, and has cracked red lips, non-purulent conjunctivitis, a rash and unilateral cervical lymphadenopathy of 2 cm. What is the priority?","options":["Await desquamation to confirm the diagnosis","IV immunoglobulin and aspirin, with echocardiography","IV antibiotics alone","Oral penicillin for 10 days","Discharge with antipyretics"],"answer":1,"keyLetter":"B","explanation":"Kawasaki disease: fever ≥5 days plus 4 of the 5 features. IVIG within 10 days prevents coronary artery aneurysms, which develop in about one-third of untreated children within 6 weeks. Peeling of the fingers belongs to the second week — waiting for it wastes the window."},
  {"id":"pedsa1-9-20","src":"p1","num":"9.20","kind":"sba","block":"Block 9 · Infection and Immunity 24 QUESTIONS · HIGHEST WEIGHT","page":58,"stem":"In Kawasaki disease, which laboratory change classically occurs in the second week?","options":["Neutropenia","A rising platelet count","Falling CRP with a normal ESR","Thrombocytopenia","Eosinophilia"],"answer":1,"keyLetter":"B","explanation":"Inflammatory markers (CRP, ESR, white cell count) are high from the start; the platelet count rises in week 2. Echocardiography is done at diagnosis and again at 4–6 weeks."},
  {"id":"pedsa1-9-21","src":"p1","num":"9.21","kind":"sba","block":"Block 9 · Infection and Immunity 24 QUESTIONS · HIGHEST WEIGHT","page":59,"stem":"A 5-year-old contact of a smear-positive adult has a Mantoux induration of 8 mm. He had BCG as a neonate and is asymptomatic. What does this mean under UK (NICE) guidance?","options":["The test is positive because of BCG and can be ignored","The test is positive; he should be assessed and given chemoprophylaxis for latent TB if active disease is excluded","The cut-off is 15 mm in BCG-vaccinated children","Only the erythema should be measured","He needs no follow-up as he is well"],"answer":1,"keyLetter":"B","explanation":"≥5 mm induration is positive regardless of BCG in the UK, and only the induration is measured. Latent TB is treated with rifampicin + isoniazid for 3 months or isoniazid alone for 6 months."},
  {"id":"pedsa1-9-22","src":"p1","num":"9.22","kind":"sba","block":"Block 9 · Infection and Immunity 24 QUESTIONS · HIGHEST WEIGHT","page":59,"stem":"A 4-month-old born to an HIV-positive mother needs testing. Which test is appropriate?","options":["HIV antibody test","HIV DNA PCR or viral load assay","CD4 count alone","Western blot","Wait until 18 months"],"answer":1,"keyLetter":"B","explanation":"Maternal IgG crosses the placenta, so antibody tests show exposure, not infection, until 18 months. Infection is excluded by at least two negative viral genome tests after stopping post-exposure prophylaxis, confirmed by loss of maternal antibody after 18 months."},
  {"id":"pedsa1-9-23","src":"p1","num":"9.23","kind":"sba","block":"Block 9 · Infection and Immunity 24 QUESTIONS · HIGHEST WEIGHT","page":60,"stem":"Which vaccine must NOT be given to a child known to be HIV-positive?","options":["Inactivated polio","BCG","Hepatitis B","Pneumococcal conjugate","Influenza"],"answer":1,"keyLetter":"B","explanation":"BCG is a live vaccine and risks dissemination. Live vaccines are also contraindicated in other immunocompromised children, those on or in contact with immunosuppressive therapy, and in pregnancy. Children with HIV should be vaccinated against influenza, hepatitis A and B, and varicella."},
  {"id":"pedsa1-9-24","src":"p1","num":"9.24","kind":"sba","block":"Block 9 · Infection and Immunity 24 QUESTIONS · HIGHEST WEIGHT","page":60,"stem":"A boy has had two episodes of meningococcal meningitis. Which investigation is most appropriate?","options":["Immunoglobulin levels","Nitroblue tetrazolium test","Complement function testing (CH50 and AP50)","Lymphocyte subsets","Sweat test"],"answer":2,"keyLetter":"C","explanation":"Recurrent neisserial infection = terminal complement component deficiency until proven otherwise. Compare: abscesses and granulomas → NBT test for chronic granulomatous disease; infections after 6 months with bronchiectasis → antibody defect; severe early infections with thrush and diarrhoea → T-cell defect."},
  {"id":"pedsa1-m-1","src":"p1","num":"M1","kind":"mock","block":"Mixed mock paper — 10 questions across all of Part 1","page":67,"stem":"Which is the correct compression-to-ventilation ratio in newborn resuscitation?","options":["15 : 2","30 : 2","3 : 1","5 : 1","Continuous compressions"],"answer":2,"keyLetter":"C","explanation":"90 compressions to 30 breaths = 120 events per minute. Older children get 15 : 2. The newborn ratio reflects the hypoxic cause of arrest."},
  {"id":"pedsa1-m-2","src":"p1","num":"M2","kind":"mock","block":"Mixed mock paper — 10 questions across all of Part 1","page":67,"stem":"At what age does a term infant's weight usually triple?","options":["4 months","6 months","12 months","2 years","4 years"],"answer":2,"keyLetter":"C","explanation":"Doubles at 4–5 months, triples at 12 months. Height doubles at 4 years and triples at 12 years."},
  {"id":"pedsa1-m-3","src":"p1","num":"M3","kind":"mock","block":"Mixed mock paper — 10 questions across all of Part 1","page":68,"stem":"A child weighing 30 kg needs maintenance fluid. What is the 24-hour volume?","options":["1500 ml","1700 ml","1800 ml","2000 ml","3000 ml"],"answer":1,"keyLetter":"B","explanation":"1000 (first 10 kg) + 500 (second 10 kg) + 200 (20 ml/kg × 10) = 1700 ml."},
  {"id":"pedsa1-m-4","src":"p1","num":"M4","kind":"mock","block":"Mixed mock paper — 10 questions across all of Part 1","page":68,"stem":"Which statement about the anterior fontanelle is correct?","options":["It closes by 8 weeks","It closes between 12 and 18 months","A tense fontanelle in a crying baby always means raised pressure","Its size is a reliable measure of brain growth","It should be closed at birth"],"answer":1,"keyLetter":"B","explanation":"The posterior fontanelle closes by 8 weeks. A tense fontanelle in a baby who is not crying suggests raised intracranial pressure and needs cranial ultrasound."},
  {"id":"pedsa1-m-5","src":"p1","num":"M5","kind":"mock","block":"Mixed mock paper — 10 questions across all of Part 1","page":68,"stem":"All of the following are live vaccines EXCEPT:","options":["MMR","BCG","Rotavirus","Oral polio (Sabin)","Inactivated polio (Salk)"],"answer":4,"keyLetter":"E","explanation":"Live vaccines must not be given to immunocompromised children, those on or in contact with immunosuppressive therapy, or in pregnancy."},
  {"id":"pedsa1-m-6","src":"p1","num":"M6","kind":"mock","block":"Mixed mock paper — 10 questions across all of Part 1","page":69,"stem":"Which is the strongest indicator that a child with gastroenteritis is shocked rather than clinically dehydrated?","options":["Sunken eyes","Dry mucous membranes","Reduced skin turgor","Capillary refill of 4 seconds with mottled cold peripheries","Decreased urine output"],"answer":3,"keyLetter":"D","explanation":"Shock (>10% loss) adds pale or mottled skin, cold extremities, weak pulses and prolonged capillary refill. Hypotension appears later still."},
  {"id":"pedsa1-m-7","src":"p1","num":"M7","kind":"mock","block":"Mixed mock paper — 10 questions across all of Part 1","page":69,"stem":"A 3-year-old has fever, drooling and stridor and is sitting forward refusing to lie down. What must be avoided?","options":["Calling for senior and anaesthetic help","Keeping the child calm on the parent's lap","Examining the throat with a tongue depressor","Giving oxygen if tolerated","Preparing for intubation"],"answer":2,"keyLetter":"C","explanation":"Suspected epiglottitis — examining or distressing the child can precipitate complete airway obstruction. This is an upper airway obstruction presentation of the seriously ill child. ADDED"},
  {"id":"pedsa1-m-8","src":"p1","num":"M8","kind":"mock","block":"Mixed mock paper — 10 questions across all of Part 1","page":69,"stem":"Which is the investigation of choice for suspected Hirschsprung disease?","options":["Barium enema","Anorectal manometry","Suction rectal biopsy","Abdominal ultrasound","Plain abdominal X-ray"],"answer":2,"keyLetter":"C","explanation":"Absent ganglion cells with large acetylcholinesterase-positive nerve trunks. Suspect it with delayed meconium, no soiling, and an empty rectum."},
  {"id":"pedsa1-m-9","src":"p1","num":"M9","kind":"mock","block":"Mixed mock paper — 10 questions across all of Part 1","page":70,"stem":"A previously well 9-week-old is found dead in his cot. Which statement is correct?","options":["A postmortem is rarely needed","The parents should not be allowed to see the baby","A paediatrician takes a detailed history and examines the baby, samples are taken, and agencies communicate","Police involvement implies the family is under suspicion of a crime","SIDS is the commonest cause of death in the first month of life"],"answer":2,"keyLetter":"C","explanation":"SIDS is the commonest cause of death between 1 month and 1 year (peak 2–4 months). The coroner will usually order a postmortem, agencies must communicate, and the family should be offered the chance to see and hold the baby, with bereavement support and follow-up."},
  {"id":"pedsa1-m-10","src":"p1","num":"M10","kind":"mock","block":"Mixed mock paper — 10 questions across all of Part 1","page":70,"stem":"Which single feature would most change your management of a febrile 2-year-old with a rash?","options":["A temperature of 39.5 °C rather than 38.5 °C","The rash does not blanch under a glass","The rash is itchy","An older sibling has a cold","The child has had paracetamol"],"answer":1,"keyLetter":"B","explanation":"A non-blanching rash in a febrile child means meningococcal sepsis until proven otherwise — antibiotics now. The height of the fever does not predict serious bacterial infection."},
  {"id":"pedsa1-10-1","src":"p1","num":"10.1","kind":"emq","block":"Block 10 · EMQ Sets + Mixed Mock Paper 35 QUESTIONS","setTitle":"The vomiting infant","page":61,"stem":"A 5-week-old boy vomits forcefully after every feed. The vomit is milky, he is hungry immediately afterwards, and he has lost 300 g. Sodium 131, potassium 3.0, chloride 88 mmol/L.","options":["Gastro-oesophageal reflux","Pyloric stenosis","Malrotation with volvulus","Intussusception","Necrotising enterocolitis","Hirschsprung disease","Cow's-milk protein allergy","Raised intracranial pressure","Pertussis","Urinary tract infection"],"answer":1,"keyLetter":"B","explanation":"B — Pyloric stenosis. Non-bilious projectile vomiting at 2–8 weeks with hypochloraemic hypokalaemic alkalosis. Correct electrolytes before pyloromyotomy."},
  {"id":"pedsa1-10-2","src":"p1","num":"10.2","kind":"emq","block":"Block 10 · EMQ Sets + Mixed Mock Paper 35 QUESTIONS","setTitle":"The vomiting infant","page":61,"stem":"A 2-day-old term infant vomits green fluid. The abdomen is soft and he is otherwise well.","options":["Gastro-oesophageal reflux","Pyloric stenosis","Malrotation with volvulus","Intussusception","Necrotising enterocolitis","Hirschsprung disease","Cow's-milk protein allergy","Raised intracranial pressure","Pertussis","Urinary tract infection"],"answer":2,"keyLetter":"C","explanation":"C — Malrotation with volvulus. Bilious vomiting in a neonate is obstruction until proven otherwise — urgent upper GI contrast study."},
  {"id":"pedsa1-10-3","src":"p1","num":"10.3","kind":"emq","block":"Block 10 · EMQ Sets + Mixed Mock Paper 35 QUESTIONS","setTitle":"The vomiting infant","page":61,"stem":"A 27-week infant on day 11, three days into increasing formula feeds, has a distended shiny abdomen, bile-stained aspirates and fresh blood in the nappy.","options":["Gastro-oesophageal reflux","Pyloric stenosis","Malrotation with volvulus","Intussusception","Necrotising enterocolitis","Hirschsprung disease","Cow's-milk protein allergy","Raised intracranial pressure","Pertussis","Urinary tract infection"],"answer":4,"keyLetter":"E","explanation":"E — Necrotising enterocolitis. X-ray: intramural and portal venous gas. Stop feeds, antibiotics, parenteral nutrition; surgery for perforation."},
  {"id":"pedsa1-10-4","src":"p1","num":"10.4","kind":"emq","block":"Block 10 · EMQ Sets + Mixed Mock Paper 35 QUESTIONS","setTitle":"The vomiting infant","page":62,"stem":"A 10-month-old has episodes of screaming with pallor and drawing up the legs, is lethargic in between, and has vomited. A mass is felt in the right upper quadrant.","options":["Gastro-oesophageal reflux","Pyloric stenosis","Malrotation with volvulus","Intussusception","Necrotising enterocolitis","Hirschsprung disease","Cow's-milk protein allergy","Raised intracranial pressure","Pertussis","Urinary tract infection"],"answer":3,"keyLetter":"D","explanation":"D — Intussusception. Ultrasound target sign; IV fluids then air enema (75% success)."},
  {"id":"pedsa1-10-5","src":"p1","num":"10.5","kind":"emq","block":"Block 10 · EMQ Sets + Mixed Mock Paper 35 QUESTIONS","setTitle":"The vomiting infant","page":62,"stem":"A 4-month-old posset after most feeds, is thriving on the 50th centile, and is otherwise entirely well. The mother is exhausted by the laundry.","options":["Gastro-oesophageal reflux","Pyloric stenosis","Malrotation with volvulus","Intussusception","Necrotising enterocolitis","Hirschsprung disease","Cow's-milk protein allergy","Raised intracranial pressure","Pertussis","Urinary tract infection"],"answer":0,"keyLetter":"A","explanation":"A — Gastro-oesophageal reflux. Uncomplicated reflux: reassurance, feeding assessment, smaller more frequent feeds, thickeners. Nearly all resolve by 12 months."},
  {"id":"pedsa1-10-6","src":"p1","num":"10.6","kind":"emq","block":"Block 10 · EMQ Sets + Mixed Mock Paper 35 QUESTIONS","setTitle":"Fever and a rash","page":62,"stem":"A 5-year-old has a sore throat and a fine erythematous rash that feels like sandpaper, denser in the axillae, with pallor around the mouth and a red tongue with prominent papillae.","options":["Measles","Rubella","Roseola infantum","Parvovirus B19","Scarlet fever","Meningococcal septicaemia","Chickenpox","Hand, foot and mouth disease","Kawasaki disease","Staphylococcal scalded skin syndrome"],"answer":4,"keyLetter":"E","explanation":"E — Scarlet fever. Group A streptococcal exotoxin. Penicillin V for 10 days to prevent rheumatic fever and glomerulonephritis."},
  {"id":"pedsa1-10-7","src":"p1","num":"10.7","kind":"emq","block":"Block 10 · EMQ Sets + Mixed Mock Paper 35 QUESTIONS","setTitle":"Fever and a rash","page":62,"stem":"A 7-year-old has bright red cheeks followed by a lace-like rash on the arms and trunk. He is otherwise well. Several classmates are affected.","options":["Measles","Rubella","Roseola infantum","Parvovirus B19","Scarlet fever","Meningococcal septicaemia","Chickenpox","Hand, foot and mouth disease","Kawasaki disease","Staphylococcal scalded skin syndrome"],"answer":3,"keyLetter":"D","explanation":"D — Parvovirus B19. Erythema infectiosum (fifth disease). Warn about contact with pregnant women (fetal hydrops) and with children who have haemolytic anaemia (aplastic crisis)."},
  {"id":"pedsa1-10-8","src":"p1","num":"10.8","kind":"emq","block":"Block 10 · EMQ Sets + Mixed Mock Paper 35 QUESTIONS","setTitle":"Fever and a rash","page":63,"stem":"A 4-year-old is unwell with fever, cough, coryza and red eyes. White spots are seen on the buccal mucosa. Two days later a maculopapular rash starts behind the ears and spreads downward.","options":["Measles","Rubella","Roseola infantum","Parvovirus B19","Scarlet fever","Meningococcal septicaemia","Chickenpox","Hand, foot and mouth disease","Kawasaki disease","Staphylococcal scalded skin syndrome"],"answer":0,"keyLetter":"A","explanation":"A — Measles. Koplik spots and the 3 Cs. Complications: encephalitis (1 in 5000, mortality 15%) and SSPE (1 in 100,000, 7 years later)."},
  {"id":"pedsa1-10-9","src":"p1","num":"10.9","kind":"emq","block":"Block 10 · EMQ Sets + Mixed Mock Paper 35 QUESTIONS","setTitle":"Fever and a rash","page":63,"stem":"A 3-year-old has a febrile illness with a rapidly spreading rash of irregular non-blanching lesions larger than 5 mm, some with necrotic centres.","options":["Measles","Rubella","Roseola infantum","Parvovirus B19","Scarlet fever","Meningococcal septicaemia","Chickenpox","Hand, foot and mouth disease","Kawasaki disease","Staphylococcal scalded skin syndrome"],"answer":5,"keyLetter":"F","explanation":"F — Meningococcal septicaemia. IM benzylpenicillin immediately, then urgent transfer. Can kill a healthy child within hours."},
  {"id":"pedsa1-10-10","src":"p1","num":"10.10","kind":"emq","block":"Block 10 · EMQ Sets + Mixed Mock Paper 35 QUESTIONS","setTitle":"Fever and a rash","page":63,"stem":"A 6-year-old has crops of itchy vesicles on an erythematous base, appearing at different stages over several days, starting on the head and trunk.","options":["Measles","Rubella","Roseola infantum","Parvovirus B19","Scarlet fever","Meningococcal septicaemia","Chickenpox","Hand, foot and mouth disease","Kawasaki disease","Staphylococcal scalded skin syndrome"],"answer":6,"keyLetter":"G","explanation":"G — Chickenpox. Lesions at different stages simultaneously is the hallmark. Watch for secondary bacterial infection (fever settles then recurs) and VZV cerebellitis a week after the rash."},
  {"id":"pedsa1-10-11","src":"p1","num":"10.11","kind":"emq","block":"Block 10 · EMQ Sets + Mixed Mock Paper 35 QUESTIONS","setTitle":"Neonatal jaundice","page":63,"stem":"A term boy of a group O mother becomes jaundiced at 14 hours. Bilirubin 180 µmol/L, haemoglobin 168 g/L, direct antiglobulin test positive. There is no hepatosplenomegaly.","options":["Physiological jaundice","Breast milk jaundice","ABO incompatibility","Rhesus haemolytic disease","G6PD deficiency","Biliary atresia","Congenital hypothyroidism","Urinary tract infection","Congenital infection","Crigler–Najjar syndrome"],"answer":2,"keyLetter":"C","explanation":"C — ABO incompatibility. Peaks at 12–72 hours, less severe than rhesus disease, no hepatosplenomegaly, haemoglobin normal or slightly low. Now more common than rhesus disease."},
  {"id":"pedsa1-10-12","src":"p1","num":"10.12","kind":"emq","block":"Block 10 · EMQ Sets + Mixed Mock Paper 35 QUESTIONS","setTitle":"Neonatal jaundice","page":64,"stem":"A 5-week-old thriving breastfed girl remains jaundiced. Her stools are pale and putty-coloured, her urine is dark, and the liver edge is 3 cm below the costal margin.","options":["Physiological jaundice","Breast milk jaundice","ABO incompatibility","Rhesus haemolytic disease","G6PD deficiency","Biliary atresia","Congenital hypothyroidism","Urinary tract infection","Congenital infection","Crigler–Najjar syndrome"],"answer":5,"keyLetter":"F","explanation":"F — Biliary atresia. Conjugated hyperbilirubinaemia. Split the bilirubin urgently — the prognosis of the Kasai portoenterostomy depends on early surgery."},
  {"id":"pedsa1-10-13","src":"p1","num":"10.13","kind":"emq","block":"Block 10 · EMQ Sets + Mixed Mock Paper 35 QUESTIONS","setTitle":"Neonatal jaundice","page":64,"stem":"A 3-week-old breastfed baby is mildly jaundiced, feeding well and gaining weight. The split bilirubin is entirely unconjugated and the stools and urine are normal.","options":["Physiological jaundice","Breast milk jaundice","ABO incompatibility","Rhesus haemolytic disease","G6PD deficiency","Biliary atresia","Congenital hypothyroidism","Urinary tract infection","Congenital infection","Crigler–Najjar syndrome"],"answer":1,"keyLetter":"B","explanation":"B — Breast milk jaundice. Up to 15% of healthy breastfed infants; benign; fades by 12 weeks. Continue breastfeeding — but only after conjugated jaundice has been excluded."},
  {"id":"pedsa1-10-14","src":"p1","num":"10.14","kind":"emq","block":"Block 10 · EMQ Sets + Mixed Mock Paper 35 QUESTIONS","setTitle":"Neonatal jaundice","page":64,"stem":"A 6-week-old is jaundiced, constipated, feeds slowly and has a large tongue and a hoarse cry. The blood spot result has not been checked.","options":["Physiological jaundice","Breast milk jaundice","ABO incompatibility","Rhesus haemolytic disease","G6PD deficiency","Biliary atresia","Congenital hypothyroidism","Urinary tract infection","Congenital infection","Crigler–Najjar syndrome"],"answer":6,"keyLetter":"G","explanation":"G — Congenital hypothyroidism. Prolonged unconjugated jaundice may precede coarse facies, dry skin, hypotonia and constipation. Detected on the day 5 blood spot screen."},
  {"id":"pedsa1-10-15","src":"p1","num":"10.15","kind":"emq","block":"Block 10 · EMQ Sets + Mixed Mock Paper 35 QUESTIONS","setTitle":"Neonatal jaundice","page":64,"stem":"A male infant of Mediterranean parents becomes deeply jaundiced on day 2. The blood film shows haemolysis; the direct antiglobulin test is negative.","options":["Physiological jaundice","Breast milk jaundice","ABO incompatibility","Rhesus haemolytic disease","G6PD deficiency","Biliary atresia","Congenital hypothyroidism","Urinary tract infection","Congenital infection","Crigler–Najjar syndrome"],"answer":4,"keyLetter":"E","explanation":"E — G6PD deficiency. X-linked, so mainly boys; common in Mediterranean, Middle Eastern, Far Eastern and African populations. Coombs-negative haemolysis. Avoid precipitant drugs and foods."},
  {"id":"pedsa1-10-16","src":"p1","num":"10.16","kind":"emq","block":"Block 10 · EMQ Sets + Mixed Mock Paper 35 QUESTIONS","setTitle":"The child who is not growing","page":65,"stem":"A 9-year-old girl is on the 0.4th height centile with a weight on the 25th. She is well, has no dysmorphic features, but has had recurrent ear infections.","options":["Familial short stature","Constitutional delay","Turner syndrome","Coeliac disease","Hypothyroidism","Growth hormone deficiency","Inadequate intake","Psychosocial deprivation","Cystic fibrosis","Cushing syndrome"],"answer":2,"keyLetter":"C","explanation":"C — Turner syndrome. Every short girl gets a karyotype; the phenotype can be very subtle, and recurrent otitis media is a clue."},
  {"id":"pedsa1-10-17","src":"p1","num":"10.17","kind":"emq","block":"Block 10 · EMQ Sets + Mixed Mock Paper 35 QUESTIONS","setTitle":"The child who is not growing","page":65,"stem":"A 7-year-old boy has dropped from the 50th to the 9th height centile over 3 years. His weight is now on the 91st centile and his bone age is markedly delayed. He is otherwise well.","options":["Familial short stature","Constitutional delay","Turner syndrome","Coeliac disease","Hypothyroidism","Growth hormone deficiency","Inadequate intake","Psychosocial deprivation","Cystic fibrosis","Cushing syndrome"],"answer":4,"keyLetter":"E","explanation":"E — Hypothyroidism (an endocrine cause). Short and overweight, crossing centiles down = endocrine. Acquired hypothyroidism is the commonest endocrine cause and may have few symptoms. Check TSH."},
  {"id":"pedsa1-10-18","src":"p1","num":"10.18","kind":"emq","block":"Block 10 · EMQ Sets + Mixed Mock Paper 35 QUESTIONS","setTitle":"The child who is not growing","page":65,"stem":"A 20-month-old has abdominal distension, wasted buttocks, foul stools and irritability. She was well until wheaning onto wheat-containing foods.","options":["Familial short stature","Constitutional delay","Turner syndrome","Coeliac disease","Hypothyroidism","Growth hormone deficiency","Inadequate intake","Psychosocial deprivation","Cystic fibrosis","Cushing syndrome"],"answer":3,"keyLetter":"D","explanation":"D — Coeliac disease. The \"classical\" presentation at 8–24 months. Test IgA tTG plus total IgA while she is still eating gluten."},
  {"id":"pedsa1-10-19","src":"p1","num":"10.19","kind":"emq","block":"Block 10 · EMQ Sets + Mixed Mock Paper 35 QUESTIONS","setTitle":"The child who is not growing","page":65,"stem":"A 10-month-old has fallen two weight centiles. Length and head circumference are unaffected, development is normal, and there are no symptoms or abnormal signs.","options":["Familial short stature","Constitutional delay","Turner syndrome","Coeliac disease","Hypothyroidism","Growth hormone deficiency","Inadequate intake","Psychosocial deprivation","Cystic fibrosis","Cushing syndrome"],"answer":6,"keyLetter":"G","explanation":"G — Inadequate intake. About 95% of faltering growth is non-organic. Take a detailed feeding history and a 3-day food diary before investigating."},
  {"id":"pedsa1-10-20","src":"p1","num":"10.20","kind":"emq","block":"Block 10 · EMQ Sets + Mixed Mock Paper 35 QUESTIONS","setTitle":"The child who is not growing","page":65,"stem":"A 4-year-old in foster care has been crossing centiles downwards. After 3 months in a new home he shows dramatic catch-up growth with no medical intervention.","options":["Familial short stature","Constitutional delay","Turner syndrome","Coeliac disease","Hypothyroidism","Growth hormone deficiency","Inadequate intake","Psychosocial deprivation","Cystic fibrosis","Cushing syndrome"],"answer":7,"keyLetter":"H","explanation":"H — Psychosocial deprivation. Deprivation impairs hypothalamic–pituitary function and reduces GH secretion; catch-up on removal from the environment is diagnostic."},
  {"id":"pedsa1-10-21","src":"p1","num":"10.21","kind":"emq","block":"Block 10 · EMQ Sets + Mixed Mock Paper 35 QUESTIONS","setTitle":"Respiratory distress in the newborn","page":66,"stem":"A 29-week infant develops grunting and subcostal recession within 2 hours of birth. Chest X-ray shows diffuse ground-glass shadowing with an air bronchogram.","options":["Respiratory distress syndrome","Transient tachypnoea of the newborn","Meconium aspiration","Persistent pulmonary hypertension","Pneumothorax","Congenital diaphragmatic hernia","Early-onset group B streptococcal pneumonia","Cyanotic congenital heart disease","Choanal atresia","Bronchopulmonary dysplasia"],"answer":0,"keyLetter":"A","explanation":"A — Respiratory distress syndrome. Surfactant deficiency. Antenatal steroids, CPAP and surfactant."},
  {"id":"pedsa1-10-22","src":"p1","num":"10.22","kind":"emq","block":"Block 10 · EMQ Sets + Mixed Mock Paper 35 QUESTIONS","setTitle":"Respiratory distress in the newborn","page":66,"stem":"A term baby born by elective caesarean section is tachypnoeic from 2 hours of age. The chest X-ray shows fluid in the horizontal fissure. He settles by 24 hours.","options":["Respiratory distress syndrome","Transient tachypnoea of the newborn","Meconium aspiration","Persistent pulmonary hypertension","Pneumothorax","Congenital diaphragmatic hernia","Early-onset group B streptococcal pneumonia","Cyanotic congenital heart disease","Choanal atresia","Bronchopulmonary dysplasia"],"answer":1,"keyLetter":"B","explanation":"B — Transient tachypnoea of the newborn. The commonest cause of respiratory distress in term infants — but a diagnosis of exclusion; rule out infection first."},
  {"id":"pedsa1-10-23","src":"p1","num":"10.23","kind":"emq","block":"Block 10 · EMQ Sets + Mixed Mock Paper 35 QUESTIONS","setTitle":"Respiratory distress in the newborn","page":66,"stem":"A term baby is cyanosed from 1 hour of age with only mild respiratory distress. The chest X-ray shows a normal-sized heart with oligaemic lung fields and no murmur is audible.","options":["Respiratory distress syndrome","Transient tachypnoea of the newborn","Meconium aspiration","Persistent pulmonary hypertension","Pneumothorax","Congenital diaphragmatic hernia","Early-onset group B streptococcal pneumonia","Cyanotic congenital heart disease","Choanal atresia","Bronchopulmonary dysplasia"],"answer":3,"keyLetter":"D","explanation":"D — Persistent pulmonary hypertension of the newborn. Urgent echocardiography to exclude structural heart disease and confirm raised pulmonary pressures. Treat with ventilation and inhaled nitric oxide."},
  {"id":"pedsa1-10-24","src":"p1","num":"10.24","kind":"emq","block":"Block 10 · EMQ Sets + Mixed Mock Paper 35 QUESTIONS","setTitle":"Respiratory distress in the newborn","page":66,"stem":"A ventilated preterm infant with RDS suddenly deteriorates with a rising oxygen requirement and reduced chest movement on the left.","options":["Respiratory distress syndrome","Transient tachypnoea of the newborn","Meconium aspiration","Persistent pulmonary hypertension","Pneumothorax","Congenital diaphragmatic hernia","Early-onset group B streptococcal pneumonia","Cyanotic congenital heart disease","Choanal atresia","Bronchopulmonary dysplasia"],"answer":4,"keyLetter":"E","explanation":"E — Pneumothorax. Occurs in up to 10% of infants ventilated for RDS. Transilluminate, then aspirate and insert a chest drain."},
  {"id":"pedsa1-10-25","src":"p1","num":"10.25","kind":"emq","block":"Block 10 · EMQ Sets + Mixed Mock Paper 35 QUESTIONS","setTitle":"Respiratory distress in the newborn","page":67,"stem":"A term infant has severe respiratory distress from birth, a scaphoid abdomen and bowel sounds audible in the left chest.","options":["Respiratory distress syndrome","Transient tachypnoea of the newborn","Meconium aspiration","Persistent pulmonary hypertension","Pneumothorax","Congenital diaphragmatic hernia","Early-onset group B streptococcal pneumonia","Cyanotic congenital heart disease","Choanal atresia","Bronchopulmonary dysplasia"],"answer":5,"keyLetter":"F","explanation":"F — Congenital diaphragmatic hernia. Chest X-ray is diagnostic. Do not bag-mask ventilate if avoidable — intubate and pass a nasogastric tube."}
];
